window.JIYI_DECKS = {"v":1,"decks":[{"id":"hsk1","name":"HSK 1","zh":"汉语水平考试一级","group":"HSK","desc":"The new HSK 1 word list (2025 syllabus), most common words first.","words":[["的","de","possessive/attributive particle ('s)","的, 得 and 地 are all read de; 的 links a description to a noun.",[["我的手机在哪儿？","Wǒ de shǒujī zài nǎr?","Where's my phone?"]]],["了","le","particle: action done; change of state","Read liǎo in some words, e.g. 了解 (to understand).",[["下雨了，我们回家吧。","Xiàyǔ le, wǒmen huíjiā ba.","It's raining, let's go home."]]],["我","wǒ","I; me","",[["我想喝点儿水。","Wǒ xiǎng hē diǎnr shuǐ.","I'd like some water."]]],["是","shì","to be (am, is, are)","Links nouns only: say 我很忙, not 我是忙.",[["你是学生吗？","Nǐ shì xuésheng ma?","Are you a student?"]]],["你","nǐ","you","",[["你中文说得真好！","Nǐ Zhōngwén shuō de zhēn hǎo!","Your Chinese is really good!"]]],["在","zài","to be at (a place); -ing (in progress)","",[["妈妈在家吗？","Māma zàijiā ma?","Is Mom at home?"]]],["不","bù","not; no","bú before a 4th tone (不是). Use 没 to negate 有 and past actions.",[["这个菜不好吃。","Zhège cài bù hǎochī.","This dish doesn't taste good."]]],["有","yǒu","to have; there is/are","Negated with 没 (没有), never 不有.",[["这里有超市吗？","Zhèli yǒu chāoshì ma?","Is there a supermarket around here?"]]],["他","tā","he; him","",[["他是我的老师。","Tā shì wǒ de lǎoshī.","He's my teacher."]]],["这","zhè","this","Often said zhèi before a measure word (这个 zhèi ge).",[["这是什么东西？","Zhè shì shénme dōngxi?","What is this?"]]],["个","gè","general measure word","Often unstressed in speech; 一个 is said yí ge.",[["我有一个哥哥。","Wǒ yǒu yí gè gēge.","I have an older brother."]]],["和","hé","and; with","Joins nouns only; don't use it to link two clauses.",[["我和妈妈去超市。","Wǒ hé māma qù chāoshì.","Mom and I are going to the supermarket."]]],["人","rén","person; people","",[["你是哪国人？","Nǐ shì nǎ guó rén?","Which country are you from?"]]],["说","shuō","to speak; to say","",[["你会说中文吗？","Nǐ huì shuō Zhōngwén ma?","Can you speak Chinese?"]]],["我们","wǒ men","we; us","",[["我们是同学。","Wǒmen shì tóngxué.","We're classmates."]]],["要","yào","to want; will, need to","要 = want/need/going to; 想 is the softer would like to.",[["我要去上班了。","Wǒ yào qù shàngbān le.","I have to go to work now."]]],["好","hǎo","good; well; OK","Read hào in 爱好 (hobby).",[["他的中文很好。","Tā de Zhōngwén hěn hǎo.","His Chinese is very good."]]],["一","yī","one; a","Tone shifts in speech (yí ge, yì diǎn r); said yāo in phone and room numbers.",[["我有一个问题。","Wǒ yǒu yí gè wèntí.","I have a question."]]],["会","huì","can (learned skill); will (likely)","会 = learned skill; 能 = able to; 可以 = allowed to.",[["你会开车吗？","Nǐ huì kāichē ma?","Can you drive?"]]],["也","yě","also; too","Goes before the verb: 我也去, not 也我去.",[["我也是学生。","Wǒ yě shì xuésheng.","I'm a student too."]]],["都","dōu","all; both","Goes after the subject, before the verb. Read dū in 首都 (capital).",[["我们都很好。","Wǒmen dōu hěn hǎo.","We're all fine."]]],["对","duì","right, correct; to, towards","",[["对，他是我哥哥。","Duì, tā shì wǒ gēge.","Yes, he's my older brother."]]],["到","dào","to arrive; to reach; until","",[["我们到了，下车吧。","Wǒmen dào le, xiàchē ba.","We're here, let's get out."]]],["上","shàng","on, above; last (week, month)","Also to go to: 上班 = go to work, 上课 = attend class.",[["手机在桌子上。","Shǒujī zài zhuōzi shàng.","The phone is on the table."]]],["来","lái","to come","",[["你什么时候来？","Nǐ shénme shíhou lái?","When are you coming?"]]],["很","hěn","very","Often just links an adjective (我很好) without really meaning very.",[["他今天很忙。","Tā jīntiān hěn máng.","He's very busy today."]]],["还","hái","still; also, else","Read huán = to return (还钱 = to pay money back).",[["你还要什么？","Nǐ hái yào shénme?","Anything else?"]]],["去","qù","to go","",[["明天你去哪儿？","Míngtiān nǐ qù nǎr?","Where are you going tomorrow?"]]],["她","tā","she; her","Same sound as 他 and 它 (tā); only the writing shows gender.",[["她是我妹妹。","Tā shì wǒ mèimei.","She's my younger sister."]]],["想","xiǎng","to want to; to miss (sb)","想 + verb = would like to; 想 + person = to miss sb (我想你).",[["你想吃什么？","Nǐ xiǎng chī shénme?","What do you want to eat?"]]],["给","gěi","to give; for, to (sb)","",[["我给你打电话。","Wǒ gěi nǐ dǎdiànhuà.","I'll call you."]]],["没有","méi yǒu","to not have; did not","Negates 有 and past actions (我没去); 不 is for habits and the future.",[["我没有时间。","Wǒ méiyǒu shíjiān.","I don't have time."]]],["能","néng","can; to be able to","能 = able / circumstances allow; for learned skills use 会.",[["你明天能来吗？","Nǐ míngtiān néng lái ma?","Can you come tomorrow?"]]],["那","nà","that; then, in that case","Often nèi before a measure word. Don't confuse with 哪 nǎ (which).",[["那我们明天见吧。","Nà wǒmen míngtiān jiàn ba.","Then let's meet tomorrow."]]],["他们","tā men","they; them","",[["他们是我的朋友。","Tāmen shì wǒ de péngyou.","They're my friends."]]],["看","kàn","to look at; to watch, read","",[["你看，下雪了！","Nǐ kàn, xiàxuě le!","Look, it's snowing!"]]],["做","zuò","to do; to make","",[["这个菜怎么做？","Zhège cài zěnme zuò?","How do you make this dish?"]]],["什么","shén me","what","",[["你在说什么？","Nǐ zài shuō shénme?","What are you saying?"]]],["吧","ba","particle: let's…; …right?","",[["我们一起去吧！","Wǒmen yìqǐ qù ba!","Let's go together!"]]],["点","diǎn","o'clock; to order (food)","一点 = one o'clock; 一点儿 = a little.",[["现在几点了？","Xiànzài jǐ diǎn le?","What time is it now?"]]],["可以","kě yǐ","can, may (allowed)","",[["我可以坐这儿吗？","Wǒ kěyǐ zuò zhèr ma?","Can I sit here?"]]],["大","dà","big; old (age)","Ask adults 多大; ask small children 几岁.",[["你今年多大了？","Nǐ jīnnián duō dà le?","How old are you?"]]],["下","xià","down, below; next (week, month)","下 = next (下星期), 上 = last (上星期).",[["下个星期我很忙。","Xià gè xīngqī wǒ hěn máng.","I'm busy next week."]]],["里","lǐ","inside; in","",[["家里有水果吗？","Jiālǐ yǒu shuǐguǒ ma?","Is there any fruit at home?"]]],["真","zhēn","really; real, true","",[["今天天气真好！","Jīntiān tiānqì zhēn hǎo!","The weather is really nice today!"]]],["现在","xiàn zài","now","",[["他现在不在家。","Tā xiànzài bú zàijiā.","He's not home right now."]]],["年","nián","year","No measure word: 一年, not 一个年. The same goes for 天.",[["我学中文一年了。","Wǒ xué Zhōngwén yì nián le.","I've been learning Chinese for a year."]]],["多","duō","many, much; how (+ adj.)","Don't put it alone before a noun: 很多人, not 多人.",[["超市里人很多。","Chāoshì lǐ rén hěn duō.","The supermarket is really crowded."]]],["两","liǎng","two (before measure words)","两 + measure word (两个人); 二 for counting and in numbers (十二).",[["我要两个包子。","Wǒ yào liǎng gè bāozi.","I'd like two baozi."]]],["吗","ma","question particle (yes/no)","Not added to 什么/谁/哪儿 questions; those are already questions.",[["你今天忙吗？","Nǐ jīntiān máng ma?","Are you busy today?"]]],["天","tiān","day; sky","",[["我想在这儿住三天。","Wǒ xiǎng zài zhèr zhù sān tiān.","I'd like to stay here for three days."]]],["太","tài","too (much); so","Usually 太…了: 太好了 = great!",[["太贵了！便宜一点儿吧。","Tài guì le! Piányi yìdiǎnr ba.","That's too expensive! Can you go a bit cheaper?"]]],["再","zài","again (future); then","再 = again in the future; 又 = again (already happened).",[["请再说一次。","Qǐng zàishuō yí cì.","Please say that again."]]],["呢","ne","particle: what about…?; ongoing action","",[["我很好，你呢？","Wǒ hěn hǎo, nǐ ne?","I'm good, and you?"]]],["只","zhǐ","only, just","Read zhī as the measure word for animals: 一只猫.",[["我只有十块钱。","Wǒ zhǐyǒu shí kuài qián.","I only have ten kuai."]]],["小","xiǎo","small; young","",[["这个房间太小了。","Zhège fángjiān tài xiǎo le.","This room is too small."]]],["知道","zhī dao","to know (a fact)","知道 = know a fact; 认识 = know a person.",[["你知道他的电话吗？","Nǐ zhīdao tā de diànhuà ma?","Do you know his phone number?"]]],["时候","shí hou","time, moment (when)","…的时候 = when…; for an amount of time use 时间.",[["吃饭的时候不要看手机。","Chīfàn de shíhou búyào kàn shǒujī.","Don't look at your phone while eating."]]],["问题","wèn tí","question; problem","",[["没问题，我明天来。","Méi wèntí, wǒ míngtiān lái.","No problem, I'll come tomorrow."]]],["工作","gōng zuò","to work; job","",[["你在哪儿工作？","Nǐ zài nǎr gōngzuò?","Where do you work?"]]],["事","shì","matter, thing (to do)","事 = matter/affair; a physical thing is 东西.",[["我今天有事，不能去。","Wǒ jīntiān yǒushì, bù néng qù.","I have something on today, I can't go."]]],["它","tā","it","",[["这是我的狗，它两岁了。","Zhè shì wǒ de gǒu, tā liǎng suì le.","This is my dog, he's two."]]],["后","hòu","after; behind, back","",[["下课后我们去吃饭。","Xiàkè hòu wǒmen qù chīfàn.","After class we're going to eat."]]],["家","jiā","home; family","Also a measure word for shops and companies: 一家商店.",[["我家有四口人。","Wǒ jiā yǒu sì kǒu rén.","There are four people in my family."]]],["你们","nǐ men","you (plural)","",[["你们几点下班？","Nǐmen jǐ diǎn xiàbān?","What time do you all get off work?"]]],["前","qián","front; before, ago","Time + 前 = ago: 三天前 = three days ago.",[["他是三年前来中国的。","Tā shì sān nián qiánlái Zhōngguó de.","He came to China three years ago."]]],["时间","shí jiān","time","",[["你明天有时间吗？","Nǐ míngtiān yǒu shíjiān ma?","Do you have time tomorrow?"]]],["怎么","zěn me","how; how come","怎么 + verb = how to; 怎么 + 不/没 = why (surprised).",[["去火车站怎么走？","Qù huǒchēzhàn zěnme zǒu?","How do I get to the train station?"]]],["爱","ài","to love","",[["妈妈，我爱你！","Māma, wǒ ài nǐ!","Mom, I love you!"]]],["这些","zhè xiē","these","",[["这些是你的书吗？","Zhèxiē shì nǐ de shū ma?","Are these your books?"]]],["喜欢","xǐ huan","to like","",[["我很喜欢这里。","Wǒ hěn xǐhuan zhèli.","I really like it here."]]],["吃","chī","to eat","",[["你吃饭了吗？","Nǐ chīfàn le ma?","Have you eaten?"]]],["谁","shéi","who","Also pronounced shuí.",[["请问，你找谁？","Qǐngwèn, nǐ zhǎo shuí?","Excuse me, who are you looking for?"]]],["新","xīn","new","",[["这是我的新手机。","Zhè shì wǒ de xīn shǒujī.","This is my new phone."]]],["找","zhǎo","to look for; to give change","找 = look for, not find (find = 找到); 找钱 = give change.",[["你在找什么？","Nǐ zài zhǎo shénme?","What are you looking for?"]]],["今天","jīn tiān","today","",[["今天星期几？","Jīntiān xīngqī jǐ?","What day is it today?"]]],["觉得","jué de","to think, to feel (opinion)","",[["你觉得这个怎么样？","Nǐ juéde zhège zěnmeyàng?","What do you think of this?"]]],["月","yuè","month; moon","一月 = January; 一个月 = one month (needs 个).",[["我下个月回国。","Wǒ xiàgèyuè huíguó.","I'm going back to my country next month."]]],["几","jǐ","how many (small numbers); a few","几 expects a small number (under ~10); otherwise ask 多少.",[["你要买几个？","Nǐ yào mǎi jǐ gè?","How many do you want to buy?"]]],["见","jiàn","to see; to meet","",[["我们在哪儿见？","Wǒmen zài nǎr jiàn?","Where shall we meet?"]]],["车","chē","car; vehicle","",[["路上车很多。","Lùshang chē hěn duō.","There's a lot of traffic on the road."]]],["一些","yì xiē","some; a few","",[["我会说一些中文。","Wǒ huì shuō yìxiē Zhōngwén.","I can speak some Chinese."]]],["大家","dà jiā","everyone","",[["大家都来了吗？","Dàjiā dōu lái le ma?","Is everyone here?"]]],["听","tīng","to listen; to hear","听 = listen; 听见 = actually hear.",[["你听，外边下雨了。","Nǐ tīng, wàibian xiàyǔ le.","Listen, it's raining outside."]]],["非常","fēi cháng","very; extremely","",[["这里的菜非常好吃。","Zhèli de cài fēicháng hǎochī.","The food here is really good."]]],["开","kāi","to open; to drive, to turn on","",[["能开一下门吗？","Néng kāi yíxià mén ma?","Could you open the door?"]]],["叫","jiào","to be called; to call","",[["你叫什么名字？","Nǐ jiào shénme míngzi?","What's your name?"]]],["孩子","hái zi","child; kid","",[["你的孩子几岁了？","Nǐ de háizi jǐ suì le?","How old is your child?"]]],["这里","zhè li","here","Same as 这儿; southern speakers, incl. Shanghai, prefer 这里.",[["我在这里等你。","Wǒ zài zhèli děng nǐ.","I'll wait for you here."]]],["请","qǐng","please; to treat (sb)","",[["今天我请你吃饭。","Jīntiān wǒ qǐng nǐ chīfàn.","Today the meal's on me."]]],["钱","qián","money","",[["你带钱了吗？","Nǐ dài qián le ma?","Did you bring money?"]]],["公司","gōng sī","company; office","",[["你几点到公司？","Nǐ jǐ diǎn dào gōngsī?","What time do you get to the office?"]]],["不要","bú yào","don't…!; to not want","不要 + verb = don't…! (不要说话); 别 means the same.",[["我不要这个，我要那个。","Wǒ búyào zhège, wǒ yào nàge.","I don't want this one, I want that one."]]],["本","běn","measure word for books","",[["我买了两本书。","Wǒ mǎi le liǎng běn shū.","I bought two books."]]],["回","huí","to go back, to return","",[["你几点回家？","Nǐ jǐ diǎn huíjiā?","What time are you going home?"]]],["东西","dōng xi","thing; stuff","dōng xī (two 1st tones) means east and west; thing has neutral xi.",[["我去超市买东西。","Wǒ qù chāoshì mǎi dōngxi.","I'm going to the supermarket to buy some stuff."]]],["三","sān","three","",[["三个人多少钱？","Sān gè rén duōshao qián?","How much for three people?"]]],["买","mǎi","to buy","mǎi (3rd tone) = buy; mài 卖 (4th tone) = sell.",[["你想买什么？","Nǐ xiǎng mǎi shénme?","What do you want to buy?"]]],["问","wèn","to ask (a question)","",[["我可以问你一个问题吗？","Wǒ kěyǐ wèn nǐ yí gè wèntí ma?","Can I ask you a question?"]]],["岁","suì","years (of age)","Usually no 是: 我二十岁.",[["我今年二十岁。","Wǒ jīnnián èr shí suì.","I'm twenty this year."]]],["号","hào","day of the month; number","",[["今天几月几号？","Jīntiān jǐ yuè jǐ hào?","What's the date today?"]]],["朋友","péng you","friend","",[["他是我的好朋友。","Tā shì wǒ de hǎo péngyou.","He's a good friend of mine."]]],["住","zhù","to live; to stay","",[["你住在哪儿？","Nǐ zhù zài nǎr?","Where do you live?"]]],["件","jiàn","measure word for clothes, matters","For tops and jackets, and for 事 (一件事); trousers take 条.",[["这件衣服多少钱？","Zhè jiàn yīfu duōshao qián?","How much is this piece of clothing?"]]],["那些","nà xiē","those","",[["那些人是谁？","Nàxiē rén shì shuí?","Who are those people?"]]],["水","shuǐ","water","",[["这里的水能喝吗？","Zhèli de shuǐ néng hē ma?","Can you drink the tap water here?"]]],["写","xiě","to write","",[["这个字怎么写？","Zhège zì zěnme xiě?","How do you write this character?"]]],["您","nín","you (polite)","Polite you for elders and customers; 您们 is rare in speech.",[["您要喝茶吗？","Nín yào hē chá ma?","Would you like some tea?"]]],["电话","diàn huà","phone; phone call","",[["你的电话是多少？","Nǐ de diànhuà shì duōshao?","What's your phone number?"]]],["女","nǚ","female; woman","",[["我们老师是女的。","Wǒmen lǎoshī shì nǚ de.","Our teacher is a woman."]]],["分","fēn","minute (clock time); to divide","Clock time: 三点十分; a length of time uses 分钟 (十分钟).",[["现在三点十分。","Xiànzài sān diǎn shífēn.","It's ten past three."]]],["小时","xiǎo shí","hour","Usually with 个 (两个小时); 点 is for clock time.",[["坐火车要三个小时。","Zuò huǒchē yào sān gè xiǎoshí.","It's three hours by train."]]],["有些","yǒu xiē","some (of them); a bit","有些 = some of a group (often first); 一些 = some/a few, after the verb.",[["这里有些东西很贵。","Zhèli yǒuxiē dōngxi hěn guì.","Some things here are expensive."]]],["日","rì","day; date (written)","Dates: 日 in writing, 号 in speech (五月一号).",[["今天是五月一日。","Jīntiān shì wǔ yuè yī rì.","Today is May 1st."]]],["玩","wán","to play; to have fun","",[["你想去哪儿玩？","Nǐ xiǎng qù nǎr wán?","Where do you want to go for fun?"]]],["正在","zhèng zài","in the middle of (doing)","",[["他正在吃饭。","Tā zhèngzài chīfàn.","He's eating right now."]]],["喝","hē","to drink","",[["你喝茶还是喝水？","Nǐ hē chá háishi hē shuǐ?","Would you like tea or water?"]]],["穿","chuān","to wear; to put on","穿 for clothes and shoes; hats, glasses and watches take 戴.",[["今天很冷，多穿点儿。","Jīntiān hěn lěng, duō chuān diǎnr.","It's cold today, wear something warm."]]],["学校","xué xiào","school","",[["我们学校很大。","Wǒmen xuéxiào hěn dà.","Our school is big."]]],["坐","zuò","to sit; to take (bus, train)","Same sound as 做 (to do). Driving yourself is 开车, not 坐车.",[["我们坐地铁去吧。","Wǒmen zuò dìtiě qù ba.","Let's take the metro."]]],["早","zǎo","early; good morning!","",[["你今天来得真早！","Nǐ jīntiān lái de zhēn zǎo!","You're really early today!"]]],["们","men","plural suffix for people","Not after numbers: 三个学生, not 三个学生们.",[["同学们，上课了！","Tóngxué men, shàngkè le!","OK everyone, class is starting!"]]],["认识","rèn shi","to know (sb); to recognize","认识 = know a person or character; 知道 = know a fact.",[["认识你很高兴。","Rènshi nǐ hěn gāoxìng.","Nice to meet you."]]],["睡","shuì","to sleep","",[["你昨天晚上睡得好吗？","Nǐ zuótiān wǎnshang shuì de hǎo ma?","Did you sleep well last night?"]]],["分钟","fēn zhōng","minute (duration)","",[["请等我五分钟。","Qǐng děng wǒ wǔ fēnzhōng.","Please give me five minutes."]]],["明天","míng tiān","tomorrow","",[["明天会下雨吗？","Míngtiān huì xiàyǔ ma?","Will it rain tomorrow?"]]],["四","sì","four","sì (four) vs shí (ten): southern speakers, incl. in Shanghai, often blur s and sh.",[["他住在四楼。","Tā zhù zài sì lóu.","He lives on the fourth floor."]]],["块","kuài","yuan (spoken); piece","",[["一共二十块。","Yígòng èr shí kuài.","That's twenty yuan altogether."]]],["外","wài","outside; foreign","",[["他是外国人。","Tā shì wàiguó rén.","He's a foreigner."]]],["晚上","wǎn shang","evening; night","",[["晚上我们去看电影吧。","Wǎnshang wǒmen qù kàn diànyǐng ba.","Let's go see a movie tonight."]]],["谢谢","xiè xie","thank you; to thank","",[["谢谢你，你真好！","Xièxie nǐ, nǐ zhēn hǎo!","Thank you, that's so kind of you!"]]],["学","xué","to learn; to study","",[["你在哪儿学的中文？","Nǐ zài nǎr xué de Zhōngwén?","Where did you learn Chinese?"]]],["多少","duō shao","how many; how much","Read duō shǎo when it means more or less.",[["这个多少钱？","Zhège duōshao qián?","How much is this?"]]],["妈妈","mā ma","mom; mother","Close family usually drops 的: 我妈妈.",[["我妈妈是医生。","Wǒ māma shì yīshēng.","My mom is a doctor."]]],["少","shǎo","few, little; less","",[["今天人很少。","Jīntiān rén hěn shǎo.","There aren't many people today."]]],["电影","diàn yǐng","movie, film","",[["这个电影很好看。","Zhège diànyǐng hěn hǎokàn.","This movie is really good."]]],["哪","nǎ","which","nǎ (which) vs nà 那 (that): only the tone differs. Often něi before a measure word.",[["你喜欢哪个？","Nǐ xǐhuan nǎge?","Which one do you like?"]]],["昨天","zuó tiān","yesterday","",[["昨天你去哪儿了？","Zuótiān nǐ qù nǎr le?","Where did you go yesterday?"]]],["晚","wǎn","late; evening","",[["对不起，我来晚了。","Duìbuqǐ, wǒ lái wǎn le.","Sorry, I'm late."]]],["书","shū","book","",[["这本书很有意思。","Zhè běn shū hěn yǒuyìsi.","This book is really interesting."]]],["五","wǔ","five","",[["我们下午五点见。","Wǒmen xiàwǔ wǔ diǎn jiàn.","Let's meet at five in the afternoon."]]],["先生","xiān sheng","Mr.; sir; husband","Surname first: 李先生 = Mr. Li. 我先生 = my husband.",[["李先生在家吗？","Lǐ xiānsheng zàijiā ma?","Is Mr. Li home?"]]],["男","nán","male; man","",[["那个男的是谁？","Nàge nán de shì shuí?","Who's that guy?"]]],["卖","mài","to sell","mài (4th tone) = sell; mǎi 买 (3rd tone) = buy.",[["这里卖水果吗？","Zhèli mài shuǐguǒ ma?","Do they sell fruit here?"]]],["医院","yī yuàn","hospital","",[["我明天要去医院。","Wǒ míngtiān yào qù yīyuàn.","I have to go to the hospital tomorrow."]]],["些","xiē","some; a few","After an adjective = a bit more: 便宜些 = a bit cheaper.",[["妈妈买了些苹果。","Māma mǎi le xiē píngguǒ.","Mom bought some apples."]]],["狗","gǒu","dog","Measure word 只 (一只狗); 条 is also common.",[["你家有狗吗？","Nǐ jiā yǒu gǒu ma?","Do you have a dog?"]]],["口","kǒu","mouth; measure word for family members","几口人 asks about family size; for people in general use 个.",[["你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","How many people are in your family?"]]],["学生","xué sheng","student","",[["他是这个学校的学生。","Tā shì zhège xuéxiào de xuésheng.","He's a student at this school."]]],["二","èr","two","Before a measure word use 两: 两个人, not 二个人.",[["今天是二月二号。","Jīntiān shì èr yuè èr hào.","Today is February 2nd."]]],["儿子","ér zi","son","",[["你儿子多大了？","Nǐ érzi duō dà le?","How old is your son?"]]],["歌","gē","song","Measure word is 首: 一首歌. To sing (a song) = 唱歌.",[["这首歌真好听！","Zhè shǒu gē zhēn hǎotīng!","This song sounds really nice!"]]],["半","bàn","half; and a half","半 goes before the measure word (半个小时) but after it in 一个半小时.",[["现在三点半。","Xiànzài sān diǎn bàn.","It's half past three."]]],["中国","Zhōng guó","China","",[["我很喜欢中国菜。","Wǒ hěn xǐhuan Zhōngguó cài.","I really like Chinese food."]]],["店","diàn","shop; store","Measure word for shops is 家: 一家店.",[["这家店的东西很便宜。","Zhè jiā diàn de dōngxi hěn piányi.","Things in this shop are really cheap."]]],["元","yuán","yuan (unit of Chinese money)","元 is the written form; in speech people say 块: 十五块.",[["一杯茶十五元。","Yì bēi chá shí wǔ yuán.","A cup of tea is fifteen yuan."]]],["哪里","nǎ li","where","哪里哪里 is also a modest reply to praise: \"not at all\".",[["你在哪里工作？","Nǐ zài nǎli gōngzuò?","Where do you work?"]]],["那里","nà li","there","",[["那里的天气怎么样？","Nàli de tiānqì zěnmeyàng?","What's the weather like there?"]]],["电视","diàn shì","television; TV","",[["晚上我们一起看电视吧。","Wǎnshang wǒmen yìqǐ kàn diànshì ba.","Let's watch TV together tonight."]]],["下午","xià wǔ","afternoon","",[["下午你有时间吗？","Xiàwǔ nǐ yǒu shíjiān ma?","Are you free this afternoon?"]]],["学习","xué xí","to study; to learn","",[["你在哪儿学习汉语？","Nǐ zài nǎr xuéxí Hànyǔ?","Where are you studying Chinese?"]]],["它们","tā men","they (animals or things)","Sounds the same as 他们/她们; 它们 is only for animals and things.",[["我有两只猫，它们都很小。","Wǒ yǒu liǎng zhī māo, tāmen dōu hěn xiǎo.","I have two cats, and they're both small."]]],["老师","lǎo shī","teacher","Used as a title after the surname: 王老师 = Teacher Wang.",[["王老师，您好！","Wáng lǎoshī, nín hǎo!","Hello, Teacher Wang!"]]],["六","liù","six","",[["现在六点了，回家吧。","Xiànzài liù diǎn le, huíjiā ba.","It's six o'clock, let's go home."]]],["边","biān","side; while (in 一边…一边)","",[["他一边吃饭一边看电视。","Tā yìbiān chīfàn yìbiān kàn diànshì.","He watches TV while he eats."]]],["唱","chàng","to sing","",[["你会唱中国歌吗？","Nǐ huì chàng Zhōngguó gē ma?","Can you sing any Chinese songs?"]]],["大学","dà xué","university; college","",[["你在哪个大学学习？","Nǐ zài nǎge dàxué xuéxí?","Which university do you study at?"]]],["病","bìng","illness; to be ill","病了 = got sick; 生病 = to fall ill; 看病 = to see a doctor.",[["他病了，今天不来了。","Tā bìng le, jīntiān bù lái le.","He's sick, so he's not coming today."]]],["医生","yī shēng","doctor","",[["医生说我要多休息。","Yīshēng shuō wǒ yào duō xiūxi.","The doctor says I need to rest more."]]],["名字","míng zi","name","",[["你叫什么名字？","Nǐ jiào shénme míngzi?","What's your name?"]]],["她们","tā men","they; them (females)","Sounds the same as 他们; use 他们 for mixed groups.",[["她们是我的同学。","Tāmen shì wǒ de tóngxué.","They're my classmates."]]],["今年","jīn nián","this year","",[["今年我想学开车。","Jīnnián wǒ xiǎng xué kāichē.","I want to learn to drive this year."]]],["手机","shǒu jī","mobile phone","",[["你的手机号是多少？","Nǐ de shǒujī hào shì duōshao?","What's your phone number?"]]],["忙","máng","busy","",[["今天工作忙不忙？","Jīntiān gōngzuò máng bu máng?","Are you busy at work today?"]]],["十","shí","ten","",[["我们十点见吧。","Wǒmen shí diǎn jiàn ba.","Let's meet at ten."]]],["看见","kàn jiàn","to see; to catch sight of","看 = to look or watch; 看见 = to actually see something.",[["你看见我的手机了吗？","Nǐ kànjiàn wǒ de shǒujī le ma?","Have you seen my phone?"]]],["女儿","nǚ ér","daughter","儿 is a full syllable ér here, not the erhua -r.",[["他女儿很漂亮。","Tā nǚ'ér hěn piàoliang.","His daughter is very pretty."]]],["说话","shuō huà","to speak; to talk","Verb-object word: say 说汉语, not 说话汉语.",[["你说话太快了。","Nǐ shuōhuà tài kuài le.","You talk too fast."]]],["爸爸","bà ba","dad; father","",[["爸爸今天不在家。","Bàba jīntiān bú zàijiā.","Dad isn't home today."]]],["字","zì","character; word","",[["这个字怎么读？","Zhège zì zěnme dú?","How do you read this character?"]]],["漂亮","piào liang","pretty; beautiful","",[["你的衣服真漂亮！","Nǐ de yīfu zhēn piàoliang!","Your clothes are really pretty!"]]],["高兴","gāo xìng","happy; glad","",[["认识你很高兴。","Rènshi nǐ hěn gāoxìng.","Nice to meet you."]]],["去年","qù nián","last year","",[["我是去年来中国的。","Wǒ shì qùnián lái Zhōngguó de.","I came to China last year."]]],["热","rè","hot","热 = hot (temperature); spicy is 辣 là.",[["今天太热了！","Jīntiān tài rè le!","It's way too hot today!"]]],["睡觉","shuì jiào","to sleep; to go to bed","觉 is jiào here but jué in 觉得.",[["很晚了，去睡觉吧。","Hěn wǎn le, qù shuìjiào ba.","It's late, go to bed."]]],["电脑","diàn nǎo","computer","",[["我的电脑太慢了。","Wǒ de diànnǎo tài màn le.","My computer is way too slow."]]],["第","dì","prefix for ordinal numbers","",[["这是我第一次来上海。","Zhè shì wǒ dìyī cì lái Shànghǎi.","This is my first time in Shanghai."]]],["读","dú","to read aloud; to study","读 = read aloud or study (读大学); reading silently is 看书.",[["请大家跟我读。","Qǐng dàjiā gēn wǒ dú.","Everyone, please read after me."]]],["冷","lěng","cold","",[["今天很冷，多穿点儿衣服。","Jīntiān hěn lěng, duō chuān diǎnr yīfu.","It's cold today, so wear something warm."]]],["飞机","fēi jī","airplane","",[["我们坐飞机去吧。","Wǒmen zuò fēijī qù ba.","Let's fly there."]]],["早上","zǎo shang","(early) morning","",[["你早上几点起床？","Nǐ zǎoshang jǐ diǎn qǐchuáng?","What time do you get up in the morning?"]]],["猫","māo","cat","",[["我家的猫很爱睡觉。","Wǒ jiā de māo hěn ài shuìjiào.","Our cat loves to sleep."]]],["打电话","dǎ diàn huà","to make a phone call","Call someone = 给 + person + 打电话, not 打电话他.",[["晚上给我打电话吧。","Wǎnshang gěi wǒ dǎdiànhuà ba.","Give me a call this evening."]]],["休息","xiū xi","to rest; rest","",[["你累了，休息一下吧。","Nǐ lèi le, xiūxi yíxià ba.","You're tired, take a break."]]],["有的","yǒu de","some (of them)","Comes first in the clause and is often paired: 有的…，有的….",[["有的菜很好吃，有的不好吃。","Yǒude cài hěn hǎochī, yǒude bù hǎochī.","Some dishes are tasty, some aren't."]]],["喂","wéi","hello (on the phone); hey","On the phone it's wéi; wèi is \"hey!\" or \"to feed\".",[["喂，你好！请问是小王吗？","Wéi, nǐ hǎo! Qǐngwèn shì Xiǎo Wáng ma?","Hello? Is that Xiao Wang?"]]],["房间","fáng jiān","room","",[["你的房间真大！","Nǐ de fángjiān zhēn dà!","Your room is really big!"]]],["八","bā","eight","",[["这个八块钱。","Zhège bā kuài qián.","This one is eight kuai."]]],["怎么样","zěn me yàng","how is it?; how about…?","",[["这家饭店的菜怎么样？","Zhè jiā fàndiàn de cài zěnmeyàng?","How's the food at this restaurant?"]]],["七","qī","seven","",[["小王的孩子七岁了。","Xiǎo Wáng de háizi qī suì le.","Xiao Wang's child is seven."]]],["菜","cài","dish (of food); vegetable","菜 means any dish of food, not only vegetables.",[["这个菜太好吃了！","Zhège cài tài hǎochī le!","This dish is so delicious!"]]],["衣服","yī fu","clothes","Measure word is 件: 一件衣服.",[["这件衣服多少钱？","Zhè jiàn yīfu duōshao qián?","How much is this piece of clothing?"]]],["上班","shàng bān","to go to work; to start work","",[["你每天几点上班？","Nǐ měi tiān jǐ diǎn shàngbān?","What time do you start work every day?"]]],["姐姐","jiě jie","older sister","",[["我姐姐在医院工作。","Wǒ jiějie zài yīyuàn gōngzuò.","My older sister works at a hospital."]]],["课","kè","class; lesson","",[["今天下午有课吗？","Jīntiān xiàwǔ yǒu kè ma?","Do you have class this afternoon?"]]],["国","guó","country","",[["你是哪国人？","Nǐ shì nǎ guó rén?","Which country are you from?"]]],["饭","fàn","meal; cooked rice","吃饭 means to have a meal in general, not just rice.",[["我们去吃饭吧！","Wǒmen qù chīfàn ba!","Let's go eat!"]]],["一半","yí bàn","half","",[["这个苹果给你一半。","Zhège píngguǒ gěi nǐ yíbàn.","Here, have half of this apple."]]],["家人","jiā rén","family member; family","",[["我很想我的家人。","Wǒ hěn xiǎng wǒ de jiārén.","I really miss my family."]]],["对不起","duì bu qǐ","sorry; excuse me","The usual reply is 没关系 (it's OK).",[["对不起，我来晚了。","Duìbuqǐ, wǒ lái wǎn le.","Sorry I'm late."]]],["哥哥","gē ge","older brother","",[["你有哥哥吗？","Nǐ yǒu gēge ma?","Do you have an older brother?"]]],["天气","tiān qì","weather","",[["今天天气真好！","Jīntiān tiānqì zhēn hǎo!","The weather's really nice today!"]]],["千","qiān","thousand","10,000 is 一万, not 十千.",[["这个手机三千多块。","Zhège shǒujī sān qiān duō kuài.","This phone costs over three thousand kuai."]]],["同学","tóng xué","classmate","",[["同学们，上课了！","Tóngxué men, shàngkè le!","OK everyone, class is starting!"]]],["好看","hǎo kàn","good-looking; good (film, book)","好看 for looks, films, books; 好听 for sounds; 好吃 for food.",[["这个电影很好看。","Zhège diànyǐng hěn hǎokàn.","This movie is really good."]]],["茶","chá","tea","",[["你想喝点儿茶吗？","Nǐ xiǎng hē diǎnr chá ma?","Would you like some tea?"]]],["雨","yǔ","rain","To rain = 下雨; heavy rain = 雨很大 (not 雨很多).",[["雨太大了，我们不去了。","Yǔ tài dà le, wǒmen bú qù le.","It's raining too hard, we're not going."]]],["星期","xīng qī","week; day of the week","星期一 = Monday … 星期六 = Saturday; Sunday = 星期天 or 星期日.",[["今天星期几？","Jīntiān xīngqī jǐ?","What day is it today?"]]],["雪","xuě","snow","",[["昨天晚上下雪了。","Zuótiān wǎnshang xiàxuě le.","It snowed last night."]]],["九","jiǔ","nine","",[["商店九点开门。","Shāngdiàn jiǔ diǎn kāi mén.","The shop opens at nine."]]],["妹妹","mèi mei","younger sister","",[["我妹妹还在上学。","Wǒ mèimei hái zài shàngxué.","My younger sister is still in school."]]],["女士","nǚ shì","lady; Ms.","Polite title after a surname: 王女士 = Ms Wang.",[["女士们，先生们，大家好！","Nǚshì men, xiānsheng men, dàjiā hǎo!","Hello, ladies and gentlemen!"]]],["上午","shàng wǔ","morning (before noon)","早上 = early morning; 上午 = the whole morning until noon.",[["明天上午我没有时间。","Míngtiān shàngwǔ wǒ méiyǒu shíjiān.","I'm not free tomorrow morning."]]],["贵","guì","expensive","Also polite: 您贵姓？ = What's your surname?",[["这儿的菜太贵了。","Zhèr de cài tài guì le.","The food here is too expensive."]]],["那边","nà bian","over there","",[["超市在那边。","Chāoshì zài nàbian.","The supermarket is over there."]]],["弟弟","dì di","younger brother","",[["弟弟今年上小学了。","Dìdi jīnnián shàng xiǎoxué le.","My younger brother started primary school this year."]]],["百","bǎi","hundred","In speech 200 is usually 两百 (二百 is also fine).",[["我们学校有两百个学生。","Wǒmen xuéxiào yǒu liǎng bǎi gè xuésheng.","Our school has two hundred students."]]],["好吃","hǎo chī","tasty; delicious","For drinks say 好喝, not 好吃.",[["妈妈做的饭真好吃！","Māma zuò de fàn zhēn hǎochī!","Mom's cooking is really good!"]]],["明年","míng nián","next year","",[["明年我女儿上大学。","Míngnián wǒ nǚ'ér shàng dàxué.","My daughter starts university next year."]]],["再见","zài jiàn","goodbye; see you","",[["好的，明天再见！","Hǎode, míngtiān zàijiàn!","OK, see you tomorrow!"]]],["这儿","zhè r","here","这儿 is northern; 这里 is more common in the south, incl. Shanghai.",[["你可以坐这儿。","Nǐ kěyǐ zuò zhèr.","You can sit here."]]],["哪儿","nǎ r","where","哪儿 nǎr (where?) vs 那儿 nàr (there): only the tone differs.",[["你家在哪儿？","Nǐ jiā zài nǎr?","Where do you live?"]]],["苹果","píng guǒ","apple","",[["苹果怎么卖？","Píngguǒ zěnme mài?","How much are the apples?"]]],["中午","zhōng wǔ","noon; midday","",[["中午我不回家。","Zhōngwǔ wǒ bù huíjiā.","I don't go home at noon."]]],["起床","qǐ chuáng","to get up (out of bed)","",[["孩子们还没起床。","Háizi men hái méi qǐchuáng.","The kids aren't up yet."]]],["开车","kāi chē","to drive (a car)","",[["你会开车吗？","Nǐ huì kāichē ma?","Can you drive?"]]],["出租车","chū zū chē","taxi","In speech, \"take a taxi\" is often just 打车 dǎ chē.",[["坐出租车去要多少钱？","Zuò chūzūchē qù yào duōshao qián?","How much is it to go by taxi?"]]],["这边","zhè bian","this side; over here","",[["您好，请这边走。","Nín hǎo, qǐng zhèbian zǒu.","Hello, this way please."]]],["火车","huǒ chē","train","",[["火车几点开？","Huǒchē jǐ diǎn kāi?","What time does the train leave?"]]],["便宜","pián yi","cheap","Polyphone: biàn yí means \"convenient\"; \"cheap\" is pián yi.",[["便宜一点儿，好吗？","Piányi yìdiǎnr, hǎo ma?","Could you make it a bit cheaper?"]]],["上学","shàng xué","to go to school; to attend school","",[["你女儿上学了吗？","Nǐ nǚ'ér shàngxué le ma?","Has your daughter started school yet?"]]],["牛奶","niú nǎi","(cow's) milk","",[["早上我喝一杯牛奶。","Zǎoshang wǒ hē yì bēi niúnǎi.","I have a glass of milk in the morning."]]],["女朋友","nǚ péng you","girlfriend","Means a romantic partner; a female friend is just 朋友.",[["他有女朋友吗？","Tā yǒu nǚpéngyou ma?","Does he have a girlfriend?"]]],["上课","shàng kè","to attend class; to start class","",[["我们八点上课。","Wǒmen bā diǎn shàngkè.","Our class starts at eight."]]],["听见","tīng jiàn","to hear","听 = to listen; 听见 = to actually hear something.",[["你听见了吗？","Nǐ tīngjiàn le ma?","Did you hear that?"]]],["男朋友","nán péng you","boyfriend","",[["她男朋友是医生。","Tā nánpéngyou shì yīshēng.","Her boyfriend is a doctor."]]],["下班","xià bān","to get off work","",[["爸爸还没下班。","Bàba hái méi xiàbān.","Dad isn't off work yet."]]],["水果","shuǐ guǒ","fruit","",[["你喜欢吃什么水果？","Nǐ xǐhuan chī shénme shuǐguǒ?","What fruit do you like?"]]],["读书","dú shū","to study; to be at school","Often means \"to be a student\", not just \"to read a book\".",[["她儿子在大学读书。","Tā érzi zài dàxué dúshū.","Her son is studying at university."]]],["那儿","nà r","there","",[["那儿有很多人。","Nàr yǒu hěn duō rén.","There are lots of people there."]]],["商店","shāng diàn","shop; store","",[["学校前边有一个商店。","Xuéxiào qiánbian yǒu yí gè shāngdiàn.","There's a shop in front of the school."]]],["鸡蛋","jī dàn","(chicken) egg","",[["早饭我吃了两个鸡蛋。","Zǎofàn wǒ chī le liǎng gè jīdàn.","I had two eggs for breakfast."]]],["没关系","méi guān xi","it's OK; never mind","",[["没关系，明天再说吧。","Méiguānxi, míngtiān zàishuō ba.","It's fine, let's talk about it tomorrow."]]],["零","líng","zero","Fills a 0 inside numbers: 一百零五 = 105.",[["现在是两点零五分。","Xiànzài shì liǎng diǎn líng wǔ fēn.","It's 2:05 now."]]],["桌子","zhuō zi","table; desk","",[["你的书在桌子上。","Nǐ de shū zài zhuōzi shàng.","Your book is on the table."]]],["白天","bái tiān","daytime; during the day","",[["白天我要工作，晚上有时间。","Báitiān wǒ yào gōngzuò, wǎnshang yǒu shíjiān.","I work during the day but I'm free in the evening."]]],["请问","qǐng wèn","excuse me, may I ask…","Use 请问 to start a polite question; 对不起 is for apologizing.",[["请问，医院在哪儿？","Qǐngwèn, yīyuàn zài nǎr?","Excuse me, where's the hospital?"]]],["哪些","nǎ xiē","which (plural)","",[["你喜欢哪些菜？","Nǐ xǐhuan nǎxiē cài?","Which dishes do you like?"]]],["晚饭","wǎn fàn","dinner; supper","",[["晚饭吃什么？","Wǎnfàn chī shénme?","What's for dinner?"]]],["小学","xiǎo xué","primary school","",[["她是小学老师。","Tā shì xiǎoxué lǎoshī.","She's a primary school teacher."]]],["饭店","fàn diàn","restaurant; hotel","Can be a restaurant or a hotel; names like 北京饭店 are hotels.",[["这家饭店的饺子很好吃。","Zhè jiā fàndiàn de jiǎozi hěn hǎochī.","The dumplings at this restaurant are great."]]],["中学","zhōng xué","middle school; high school","中学 covers both junior (初中) and senior (高中) high school.",[["我们是中学同学。","Wǒmen shì zhōngxué tóngxué.","We were classmates in high school."]]],["面包","miàn bāo","bread","",[["面包和牛奶在桌子上。","Miànbāo hé niúnǎi zài zhuōzi shàng.","The bread and milk are on the table."]]],["生病","shēng bìng","to fall ill; to get sick","",[["你生病了吗？","Nǐ shēngbìng le ma?","Are you sick?"]]],["好听","hǎo tīng","nice to listen to","",[["她唱歌很好听。","Tā chànggē hěn hǎotīng.","She sings beautifully."]]],["大学生","dà xué shēng","university student","",[["他哥哥是大学生。","Tā gēge shì dàxuésheng.","His older brother is a university student."]]],["超市","chāo shì","supermarket","",[["我去超市买点儿水果。","Wǒ qù chāoshì mǎi diǎnr shuǐguǒ.","I'm going to the supermarket for some fruit."]]],["椅子","yǐ zi","chair","Measure word is 把: 一把椅子.",[["椅子在那儿，你坐吧。","Yǐzi zài nàr, nǐ zuò ba.","There's a chair over there, have a seat."]]],["小朋友","xiǎo péng you","child; kid","Friendly word for children, not \"little friend\".",[["小朋友，你几岁了？","Xiǎopéngyou, nǐ jǐ suì le?","How old are you, little one?"]]],["午饭","wǔ fàn","lunch","",[["我们去哪儿吃午饭？","Wǒmen qù nǎr chī wǔfàn?","Where shall we go for lunch?"]]],["做饭","zuò fàn","to cook (a meal)","",[["今天谁做饭？","Jīntiān shuí zuòfàn?","Who's cooking today?"]]],["下雨","xià yǔ","to rain","",[["明天会下雨吗？","Míngtiān huì xiàyǔ ma?","Will it rain tomorrow?"]]],["杯子","bēi zi","cup; glass","As a measure word it's just 杯: 一杯水 = a glass of water.",[["这个杯子是谁的？","Zhège bēizi shì shuí de?","Whose cup is this?"]]],["中文","Zhōng wén","Chinese (language)","",[["你的中文很好！","Nǐ de Zhōngwén hěn hǎo!","Your Chinese is really good!"]]],["早饭","zǎo fàn","breakfast","",[["你吃早饭了吗？","Nǐ chī zǎofàn le ma?","Have you had breakfast?"]]],["一点儿","yì diǎn r","a little; a bit","一点儿 goes after adjectives (慢一点儿); 有点儿 goes before them (有点儿冷).",[["请说慢一点儿。","Qǐng shuō màn yìdiǎnr.","Please speak a bit more slowly."]]],["书店","shū diàn","bookstore","",[["这个书店的书很多。","Zhège shūdiàn de shū hěn duō.","This bookstore has lots of books."]]],["星期天","xīng qī tiān","Sunday","",[["星期天你想做什么？","Xīngqītiān nǐ xiǎng zuò shénme?","What do you want to do on Sunday?"]]],["看病","kàn bìng","to see a doctor","For a patient: to see a doctor; for a doctor: to treat patients.",[["她明天去医院看病。","Tā míngtiān qù yīyuàn kànbìng.","She's going to see a doctor tomorrow."]]],["电影院","diàn yǐng yuàn","cinema","",[["电影院在超市后边。","Diànyǐngyuàn zài chāoshì hòubian.","The cinema is behind the supermarket."]]],["下课","xià kè","to finish class","",[["下课后你去哪儿？","Xiàkè hòu nǐ qù nǎr?","Where are you going after class?"]]],["米饭","mǐ fàn","(cooked) rice","Measure word 碗: 一碗米饭. Uncooked rice is 米 or 大米.",[["我要一碗米饭。","Wǒ yào yì wǎn mǐfàn.","I'd like a bowl of rice."]]],["有点儿","yǒu diǎn r","a little; somewhat","Goes before adjectives, mostly negative ones: 有点儿累, not 有点儿好.",[["今天有点儿冷。","Jīntiān yǒudiǎnr lěng.","It's a bit cold today."]]],["饺子","jiǎo zi","dumpling","",[["我们一起包饺子吧！","Wǒmen yìqǐ bāo jiǎozi ba!","Let's make dumplings together!"]]],["小学生","xiǎo xué shēng","primary school pupil","",[["他还是个小学生。","Tā háishi gè xiǎoxuésheng.","He's still just a primary school kid."]]],["外边","wài bian","outside","",[["外边下雨了。","Wàibian xiàyǔ le.","It's raining outside."]]],["中学生","zhōng xué shēng","middle or high school student","",[["他是中学生，还不能开车。","Tā shì zhōngxuésheng, hái bù néng kāichē.","He's in high school, so he can't drive yet."]]],["星期日","xīng qī rì","Sunday","Same as 星期天; 星期日 is a bit more formal or written.",[["星期日商店开门吗？","Xīngqīrì shāngdiàn kāi mén ma?","Are the shops open on Sunday?"]]],["汉语","Hàn yǔ","Chinese (language)","",[["他汉语说得很好。","Tā Hànyǔ shuō de hěn hǎo.","He speaks Chinese really well."]]],["包子","bāo zi","steamed stuffed bun","",[["包子是肉的还是菜的？","Bāozi shì ròu de háishi cài de?","Are the buns meat or vegetable?"]]],["不客气","bú kè qi","you're welcome","",[["不客气，下次再来！","Búkèqi, xiàcì zài lái!","You're welcome, come again!"]]],["汉字","hàn zì","Chinese character","",[["这个汉字怎么写？","Zhège hànzì zěnme xiě?","How do you write this character?"]]],["好玩儿","hǎo wán r","fun; amusing","In the south, incl. Shanghai, people usually say 好玩 without 儿.",[["上海有什么好玩儿的地方？","Shànghǎi yǒu shénme hǎowánr de dìfang?","What fun places are there in Shanghai?"]]],["面条儿","miàn tiáo r","noodles","In the south, incl. Shanghai, it's usually 面条 or just 面.",[["你喜欢吃面条儿吗？","Nǐ xǐhuan chī miàntiáor ma?","Do you like noodles?"]]]]},{"id":"hsk2","name":"HSK 2","zh":"汉语水平考试二级","group":"HSK","desc":"The words that are new at HSK 2 (2025 syllabus). Do HSK 1 first.","words":[["就","jiù","then; right away, as soon as","一…就… = as soon as: 我一到就给你打电话。",[["我一下班就回家。","Wǒ yíxià bān jiù huíjiā.","I go home as soon as I finish work."]]],["着","zhe","particle: ongoing action or state","Read zháo in 睡着 (to fall asleep) and 找着 (to find).",[["外面下着雨呢，别出去了。","Wàimian xià zhe yǔ ne, bié chūqù le.","It's raining outside, don't go out."]]],["啊","a","particle: softens or exclaims","Blends with the syllable before: 好啊 sounds hǎo wa, 你啊 nǐ ya, 看啊 kàn na.",[["好啊，我们一起去！","Hǎo a, wǒmen yìqǐ qù!","Sure, let's go together!"]]],["让","ràng","to let, allow; to make (sb do)","",[["妈妈不让我喝咖啡。","Māma bú ràng wǒ hē kāfēi.","Mom doesn't let me drink coffee."]]],["但","dàn","but","",[["这件衣服很好看，但太贵了。","Zhè jiàn yīfu hěn hǎokàn, dàn tài guì le.","This top looks nice, but it's too expensive."]]],["自己","zì jǐ","oneself; one's own","",[["没关系，我自己来吧。","Méiguānxi, wǒ zìjǐ lái ba.","It's fine, I'll do it myself."]]],["得","de","particle linking verb to degree/result","Also děi 'must' (我得走了) and dé 'to get'. 的/地/得 all sound de.",[["你今天来得真早！","Nǐ jīntiān lái de zhēn zǎo!","You're really early today!"]]],["过","guo","particle: have done before (experience)","Negate with 没: 没去过, never 不去过. As a verb 'to cross; to spend' it's guò.",[["我还没去过北京。","Wǒ hái méi qù guo Běijīng.","I still haven't been to Beijing."]]],["从","cóng","from","",[["从我家到公司要半个小时。","Cóng wǒ jiā dào gōngsī yào bàn gè xiǎoshí.","It takes half an hour from my home to the office."]]],["等","děng","to wait; and so on, etc.","",[["你别等我了，先吃吧。","Nǐ bié děng wǒ le, xiān chī ba.","Don't wait for me, go ahead and eat."]]],["出","chū","to go/come out; to occur","",[["地铁出问题了，我要晚点儿到。","Dìtiě chū wèntí le, wǒ yào wǎndiǎnr dào.","There's a problem with the metro, I'll be a bit late."]]],["已经","yǐ jīng","already","Usually ends with 了: 已经…了.",[["他已经回家了。","Tā yǐjīng huíjiā le.","He's already gone home."]]],["这样","zhè yàng","like this; this way","",[["你这样说，我就懂了。","Nǐ zhèyàng shuō, wǒ jiù dǒng le.","Put that way, I get it."]]],["最","zuì","most; -est","",[["你最喜欢什么菜？","Nǐ zuì xǐhuan shénme cài?","What's your favorite dish?"]]],["因为","yīn wèi","because","Often paired: 因为…所以…",[["因为下雨，我没出去。","Yīnwèi xiàyǔ, wǒ méi chūqù.","Because it was raining, I didn't go out."]]],["次","cì","measure word for times (occasions)","Word order: verb + 过 + number + 次 (我去过两次).",[["这是我第一次来上海。","Zhè shì wǒ dìyī cì lái Shànghǎi.","This is my first time in Shanghai."]]],["走","zǒu","to walk; to leave","",[["不早了，我先走了！","Bù zǎo le, wǒ xiān zǒu le!","It's getting late, I'm heading off!"]]],["但是","dàn shì","but, however","",[["我想去，但是没有时间。","Wǒ xiǎng qù, dànshì méiyǒu shíjiān.","I'd like to go, but I don't have time."]]],["时","shí","time; when (= …的时候)","A shorter, slightly more formal 的时候.",[["吃饭时别看手机。","Chīfàn shí biékàn shǒujī.","Don't look at your phone while eating."]]],["可能","kě néng","maybe; possible","",[["他可能不来了。","Tā kěnéng bù lái le.","He might not come."]]],["地","de","particle: turns word into adverb (-ly)","Also dì 'ground, place' (地上, 地铁). 的/得/地 all sound de.",[["他们高兴地笑了。","Tāmen gāoxìng de xiào le.","They laughed happily."]]],["开始","kāi shǐ","to begin, start","",[["电影已经开始了。","Diànyǐng yǐjīng kāishǐ le.","The movie has already started."]]],["跟","gēn","with; to follow","跟…一样 = the same as.",[["你跟我一起去吧！","Nǐ gēn wǒ yìqǐ qù ba!","Come with me!"]]],["打","dǎ","to hit; to play (ball games)","Very versatile: 打电话 = call, 打车 = take a taxi, 打球 = play ball.",[["你会打篮球吗？","Nǐ huì dǎlánqiú ma?","Can you play basketball?"]]],["快","kuài","fast; soon","快…了 = about to: 快到了 (almost there).",[["快点儿，车要开了！","Kuàidiǎnr, chē yào kāi le!","Hurry up, the bus is about to leave!"]]],["比","bǐ","than (comparison); to compare","Negative: 今天没有昨天冷 (不比 means 'no more … than').",[["今天比昨天冷多了。","Jīntiān bǐ zuótiān lěng duō le.","Today is much colder than yesterday."]]],["所以","suǒ yǐ","so, therefore","",[["我感冒了，所以没去上班。","Wǒ gǎnmào le, suǒyǐ méi qù shàngbān.","I had a cold, so I didn't go to work."]]],["还是","hái shi","or (in questions); still","'Or' in questions is 还是; in statements use 或者.",[["你喝茶还是咖啡？","Nǐ hē chá háishi kāfēi?","Would you like tea or coffee?"]]],["那么","nà me","so, that (much); in that case","",[["那么贵？我不买了。","Nàme guì? Wǒ bù mǎi le.","That expensive? I won't buy it then."]]],["这么","zhè me","so, this (much); like this","",[["这么晚了，你还不睡？","Zhème wǎn le, nǐ hái bú shuì?","It's so late, you're still not going to bed?"]]],["起来","qǐ lai","to get up; (after verb) start to","After verbs: 笑起来 = start laughing; 看起来 = to look, seem.",[["快起来，已经八点了！","Kuài qǐlái, yǐjīng bā diǎn le!","Get up, it's already eight!"]]],["一起","yì qǐ","together","",[["我们一起吃饭吧！","Wǒmen yìqǐ chīfàn ba!","Let's eat together!"]]],["位","wèi","polite measure word for people","Polite only: for your own group say 我们三个人, not 三位.",[["您好，请问几位？","Nín hǎo, qǐngwèn jǐ wèi?","Hello, how many people are in your party?"]]],["希望","xī wàng","to hope; hope","",[["希望你早点儿好起来。","Xīwàng nǐ zǎo diǎnr hǎo qǐlái.","Hope you get well soon."]]],["手","shǒu","hand","",[["你的手怎么这么冷？","Nǐ de shǒu zěnme zhème lěng?","Why are your hands so cold?"]]],["别","bié","don't; other","别 = 不要 (don't); 别人 = other people.",[["别走，再坐一会儿吧！","Bié zǒu, zài zuò yíhuìr ba!","Don't go, stay a bit longer!"]]],["名","míng","measure word for people; place (rank)","",[["他这次考试考了第一名！","Tā zhè cì kǎoshì kǎo le dìyī míng!","He came first in the exam this time!"]]],["长","cháng","long","Also zhǎng 'to grow': 长大 (grow up), 长高 (grow taller).",[["你的头发真长！","Nǐ de tóufa zhēn cháng!","Your hair is really long!"]]],["告诉","gào su","to tell","",[["这件事你别告诉妈妈。","Zhè jiàn shì nǐ bié gàosu māma.","Don't tell Mom about this."]]],["出来","chū lai","to come out","",[["你出来一下，我在外面。","Nǐ chūlái yíxià, wǒ zài wàimian.","Come out for a sec, I'm outside."]]],["事情","shì qing","thing, matter","",[["这件事情你知道吗？","Zhè jiàn shìqing nǐ zhīdao ma?","Do you know about this?"]]],["条","tiáo","measure word for long thin things","Also for 路, 裤子, 河 and 狗.",[["我买了两条鱼。","Wǒ mǎi le liǎng tiáo yú.","I bought two fish."]]],["拿","ná","to take; to hold, carry","",[["帮我拿一下这个包，好吗？","Bāng wǒ ná yíxià zhège bāo, hǎo ma?","Could you hold this bag for me?"]]],["高","gāo","tall; high","",[["他比我高一点儿。","Tā bǐ wǒ gāo yìdiǎnr.","He's a bit taller than me."]]],["正","zhèng","just (in the middle of); exactly","正 + verb + 呢 = in the middle of doing, like 正在.",[["我们正说你呢！","Wǒmen zhèng shuō nǐ ne!","We were just talking about you!"]]],["为什么","wèi shén me","why","",[["你为什么不高兴？","Nǐ wèishénme bù gāoxìng?","Why are you unhappy?"]]],["头","tóu","head","Neutral tou as a suffix: 里头, 外头, 馒头.",[["他笑着点了点头。","Tā xiào zhe diǎn le diǎntóu.","He smiled and nodded."]]],["准备","zhǔn bèi","to prepare; to plan to","",[["你准备好了吗？","Nǐ zhǔnbèi hǎo le ma?","Are you ready?"]]],["进","jìn","to enter, come/go in","",[["请进，不用换鞋。","Qǐngjìn, búyòng huàn xié.","Come in, no need to take off your shoes."]]],["每","měi","every, each","Usually with 都: 每天都…",[["明天每个人都要来。","Míngtiān měi gè rén dōu yào lái.","Everyone has to come tomorrow."]]],["周","zhōu","week","Same as 星期: 下周 = 下个星期; 周末 = weekend.",[["我们下周见吧！","Wǒmen xiàzhōu jiàn ba!","See you next week!"]]],["过去","guò qù","to go over (there); the past","Also 'the past': 过去的事.",[["你先过去，我马上就来。","Nǐ xiān guòqù, wǒ mǎshàng jiù lái.","You go over first, I'll be right there."]]],["送","sòng","to give (a gift); to take, see off","",[["我送你回家吧。","Wǒ sòng nǐ huíjiā ba.","Let me take you home."]]],["笑","xiào","to laugh; to smile","",[["她笑起来很好看。","Tā xiào qǐlái hěn hǎokàn.","She looks pretty when she smiles."]]],["不错","bú cuò","pretty good, not bad","Means 'pretty good' (praise), not just 'not wrong'.",[["你的汉语说得很不错！","Nǐ de Hànyǔ shuō de hěn búcuò!","Your Chinese is really good!"]]],["帮","bāng","to help","",[["你能帮我一下吗？","Nǐ néng bāng wǒ yíxià ma?","Can you help me for a sec?"]]],["完","wán","to finish; (after verb) done","",[["你吃完饭了吗？","Nǐ chī wán fàn le ma?","Have you finished eating?"]]],["站","zhàn","to stand; station, stop","As a noun: 地铁站 = metro station; 下一站 = next stop.",[["我站了一个小时，太累了。","Wǒ zhàn le yí gè xiǎoshí, tài lèi le.","I stood for an hour, I'm exhausted."]]],["路","lù","road; (bus) route","Bus lines: 九路车 = bus No. 9.",[["这条路车很多。","Zhè tiáo lù chē hěn duō.","There's a lot of traffic on this road."]]],["门","mén","door; measure word for courses","",[["走的时候别忘了关门。","Zǒu de shíhou bié wàng le guān mén.","Don't forget to close the door when you leave."]]],["花","huā","to spend (money, time); flower","",[["这个月我花了很多钱。","Zhège yuè wǒ huā le hěn duō qián.","I spent a lot of money this month."]]],["虽然","suī rán","although","Pair with 但是/可是: Chinese uses both halves, unlike English.",[["虽然很累，但是很开心。","Suīrán hěn lèi, dànshì hěn kāixīn.","Although I'm tired, I'm really happy."]]],["回来","huí lai","to come back","回来 = come back (here); 回去 = go back (there).",[["等我一下，我马上回来！","Děng wǒ yíxià, wǒ mǎshàng huílai!","Wait for me, I'll be right back!"]]],["球","qiú","ball; ball game","打球 for basketball, badminton etc.; football is 踢球.",[["下午我们去打球吧！","Xiàwǔ wǒmen qù dǎqiú ba!","Let's go play ball this afternoon!"]]],["错","cuò","wrong; mistake","Verb + 错 = do wrongly: 走错 (go the wrong way), 听错 (mishear).",[["对不起，我说错了。","Duìbuqǐ, wǒ shuō cuò le.","Sorry, I said it wrong."]]],["间","jiān","measure word for rooms","",[["这间房间很大。","Zhè jiān fángjiān hěn dà.","This room is big."]]],["跑","pǎo","to run","",[["别跑，慢点儿走！","Bié pǎo, màndiǎnr zǒu!","Don't run, slow down!"]]],["万","wàn","ten thousand","Big numbers go by 万: 十万 = 100,000; 一百万 = 1 million.",[["上海有两千多万人。","Shànghǎi yǒu liǎng qiān duō wàn rén.","Shanghai has over 20 million people."]]],["动","dòng","to move","",[["我太累了，走不动了。","Wǒ tài lèi le, zǒu bú dòng le.","I'm too tired, I can't walk any further."]]],["面","miàn","noodles; side, face","Also 'side/face' (前面, 见面) and measure word for flat things.",[["中午我想吃碗面。","Zhōngwǔ wǒ xiǎng chī wǎn miàn.","I want a bowl of noodles for lunch."]]],["下来","xià lai","to come down","",[["你下来吧，我在楼下等你。","Nǐ xiàlai ba, wǒ zài lóuxià děng nǐ.","Come down, I'm waiting for you downstairs."]]],["远","yuǎn","far","",[["不远，走路十分钟就到了。","Bù yuǎn, zǒulù shí fēnzhōng jiù dào le.","It's not far, just ten minutes on foot."]]],["快乐","kuài lè","happy (in wishes)","Mostly in wishes; to say you're happy use 开心 or 高兴.",[["祝你生日快乐！","Zhù nǐ shēngrì kuàilè!","Happy birthday!"]]],["里面","lǐ mian","inside","",[["包里面有什么？","Bāo lǐmian yǒu shénme?","What's inside the bag?"]]],["懂","dǒng","to understand","听不懂 = can't understand by ear; 看不懂 = by reading.",[["你懂我的意思吗？","Nǐ dǒng wǒ de yìsi ma?","Do you get what I mean?"]]],["过来","guò lai","to come over (here)","",[["你过来一下，我有事。","Nǐ guòlái yíxià, wǒ yǒushì.","Come here a sec, I need you for something."]]],["记得","jì de","to remember","",[["你还记得我吗？","Nǐ hái jìde wǒ ma?","Do you still remember me?"]]],["药","yào","medicine","Medicine is 'eaten': 吃药 = to take medicine.",[["这个药一天吃三次。","Zhège yào yì tiān chī sān cì.","Take this medicine three times a day."]]],["身体","shēn tǐ","body; health","",[["多运动对身体好。","Duō yùndòng duì shēntǐ hǎo.","Exercising more is good for your health."]]],["包","bāo","to wrap; bag","",[["我们一起包饺子吧！","Wǒmen yìqǐ bāo jiǎozi ba!","Let's make dumplings together!"]]],["那样","nà yàng","like that; that kind","",[["别那样说，他会不高兴的。","Bié nàyàng shuō, tā huì bù gāoxìng de.","Don't say it like that, he'll be upset."]]],["往","wǎng","towards","Directions: 往左/往右 = (go) left/right.",[["一直往前走就到了。","Yìzhí wǎng qián zǒu jiù dào le.","Go straight ahead and you'll be there."]]],["楼","lóu","building; floor","Floors count from the ground: 一楼 = ground floor.",[["我家在五楼，没有电梯。","Wǒ jiā zài wǔ lóu, méiyǒu diàntī.","I live on the 5th floor, and there's no elevator."]]],["飞","fēi","to fly","",[["从上海飞北京要两个小时。","Cóng Shànghǎi fēi Běijīng yào liǎng gè xiǎoshí.","Flying from Shanghai to Beijing takes two hours."]]],["介绍","jiè shào","to introduce","",[["我来介绍一下，这是小王。","Wǒ lái jièshào yíxià, zhè shì Xiǎo Wáng.","Let me introduce you: this is Xiao Wang."]]],["出去","chū qu","to go out","",[["我出去买点儿东西。","Wǒ chūqù mǎi diǎnr dōngxi.","I'm going out to buy a few things."]]],["眼睛","yǎn jing","eye","",[["她的眼睛很漂亮。","Tā de yǎnjing hěn piàoliang.","She has beautiful eyes."]]],["近","jìn","near, close","",[["我家离公司很近。","Wǒ jiā lí gōngsī hěn jìn.","My home is close to my office."]]],["下去","xià qu","to go down; to go on","After a verb it means 'keep on': 说下去 = keep talking.",[["你说下去，我在听。","Nǐ shuō xiàqù, wǒ zài tīng.","Go on, I'm listening."]]],["离","lí","from (distance); to leave","For distance use 离, not 从: 离这儿很近.",[["地铁站离这儿远吗？","Dìtiězhàn lí zhèr yuǎn ma?","Is the metro station far from here?"]]],["经常","jīng cháng","often","",[["我们经常一起吃饭。","Wǒmen jīngcháng yìqǐ chīfàn.","We often eat together."]]],["票","piào","ticket","",[["请问，在哪儿买票？","Qǐngwèn, zài nǎr mǎi piào?","Excuse me, where do I buy tickets?"]]],["床","chuáng","bed","Measure word 张: 一张床.",[["这张床很舒服。","Zhè zhāng chuáng hěn shūfu.","This bed is really comfortable."]]],["教","jiāo","to teach","Read jiào in 教室 (classroom).",[["你可以教我说上海话吗？","Nǐ kěyǐ jiāo wǒ shuō Shànghǎihuà ma?","Can you teach me to speak Shanghainese?"]]],["意思","yì si","meaning","一点儿小意思 = a small token (of thanks).",[["这句话是什么意思？","Zhè jù huà shì shénme yìsi?","What does this sentence mean?"]]],["忘","wàng","to forget","",[["对不起，我忘了你的名字。","Duìbuqǐ, wǒ wàng le nǐ de míngzi.","Sorry, I forgot your name."]]],["画","huà","to draw, paint; picture","画画儿 = to draw (verb 画 + noun 画儿).",[["我女儿很喜欢画画儿。","Wǒ nǚ'ér hěn xǐhuan huà huàr.","My daughter loves drawing."]]],["运动","yùn dòng","sport, exercise; to work out","",[["你平时做什么运动？","Nǐ píngshí zuò shénme yùndòng?","What exercise do you usually do?"]]],["回去","huí qu","to go back","",[["下雨了，我们回去吧。","Xiàyǔ le, wǒmen huíqu ba.","It's raining, let's go back."]]],["妻子","qī zi","wife","In speech 老婆 or 爱人 are more common.",[["他妻子是医生。","Tā qīzi shì yīshēng.","His wife is a doctor."]]],["鱼","yú","fish","",[["我不太喜欢吃鱼。","Wǒ bútài xǐhuan chī yú.","I don't really like eating fish."]]],["累","lèi","tired","",[["今天工作太累了。","Jīntiān gōngzuò tài lèi le.","Work was so tiring today."]]],["打开","dǎ kāi","to open; to turn on","",[["你把电视打开吧。","Nǐ bǎ diànshì dǎkāi ba.","Turn on the TV."]]],["肉","ròu","meat","On its own 肉 often means pork.",[["我不吃肉，只吃菜。","Wǒ bù chī ròu, zhǐ chī cài.","I don't eat meat, only vegetables."]]],["班","bān","class; shift","",[["我们班有三十个学生。","Wǒmen bān yǒu sān shí gè xuésheng.","Our class has thirty students."]]],["坏","huài","bad; broken","",[["我的手机坏了。","Wǒ de shǒujī huài le.","My phone is broken."]]],["笔","bǐ","pen; measure word for sums of money","",[["我可以用一下你的笔吗？","Wǒ kěyǐ yòng yíxià nǐ de bǐ ma?","Can I use your pen for a moment?"]]],["上面","shàng mian","on top, above","",[["你的手机在桌子上面。","Nǐ de shǒujī zài zhuōzi shàngmian.","Your phone is on the table."]]],["洗","xǐ","to wash","洗澡 = to shower/bathe; 洗手间 = restroom.",[["你先去洗个澡吧。","Nǐ xiān qù xǐ gè zǎo ba.","Go take a shower first."]]],["后面","hòu mian","behind; at the back","",[["我就在你后面。","Wǒ jiù zài nǐ hòumian.","I'm right behind you."]]],["外面","wài mian","outside","",[["外面很冷，多穿点儿衣服。","Wàimian hěn lěng, duō chuān diǎnr yīfu.","It's cold outside, put on more clothes."]]],["丈夫","zhàng fu","husband","In speech 老公 or 爱人 are more common.",[["她丈夫是老师。","Tā zhàngfu shì lǎoshī.","Her husband is a teacher."]]],["左","zuǒ","left","",[["我的左手有点儿疼。","Wǒ de zuǒ shǒu yǒudiǎnr téng.","My left hand hurts a bit."]]],["下面","xià mian","below, under; next","Also 'next, following': 下面请小王说。",[["你的鞋在床下面。","Nǐ de xié zài chuáng xiàmian.","Your shoes are under the bed."]]],["右","yòu","right","",[["往右走就是地铁站。","Wǎng yòu zǒu jiùshì dìtiězhàn.","Go right and you'll see the metro station."]]],["生日","shēng rì","birthday","",[["你的生日是几月几号？","Nǐ de shēngrì shì jǐ yuè jǐ hào?","When is your birthday?"]]],["有时","yǒu shí","sometimes","Same as 有时候, which is more common in speech.",[["我有时走路去上班。","Wǒ yǒushí zǒulù qù shàngbān.","Sometimes I walk to work."]]],["词","cí","word","词 = word; 字 = single character.",[["这个词怎么读？","Zhège cí zěnme dú?","How do you pronounce this word?"]]],["鸟","niǎo","bird","",[["你听，鸟在唱歌。","Nǐ tīng, niǎo zài chànggē.","Listen, the birds are singing."]]],["进去","jìn qu","to go in","",[["我们进去看看吧。","Wǒmen jìnqù kàn kàn ba.","Let's go in and take a look."]]],["疼","téng","to hurt, ache","Also 'to dote on': 奶奶很疼我.",[["我头有点儿疼。","Wǒ tóu yǒudiǎnr téng.","My head hurts a bit."]]],["路上","lù shang","on the way","",[["路上小心，到了给我打电话。","Lùshang xiǎoxīn, dào le gěi wǒ dǎdiànhuà.","Be careful on the way, call me when you get there."]]],["酒店","jiǔ diàn","hotel","Usually means hotel, not bar.",[["我们住的酒店离机场很近。","Wǒmen zhù de jiǔdiàn lí jīchǎng hěn jìn.","Our hotel is close to the airport."]]],["咖啡","kā fēi","coffee","",[["我每天早上喝一杯咖啡。","Wǒ měi tiān zǎoshang hē yì bēi kāfēi.","I have a cup of coffee every morning."]]],["考试","kǎo shì","exam; to take an exam","",[["这次考试难不难？","Zhè cì kǎoshì nán bunán?","Was this exam hard?"]]],["慢","màn","slow","",[["请说慢一点儿。","Qǐng shuō màn yìdiǎnr.","Please speak a bit more slowly."]]],["前面","qián mian","in front, ahead","",[["前面有一个超市。","Qiánmian yǒu yí gè chāoshì.","There's a supermarket up ahead."]]],["旁边","páng biān","beside, next to","",[["药店就在医院旁边。","Yàodiàn jiù zài yīyuàn pángbiān.","The pharmacy is right next to the hospital."]]],["帮忙","bāng máng","to help, do a favor","No object after 帮忙: say 帮我 or 帮我个忙, not 帮忙我.",[["要不要我帮忙？","Yào buyào wǒ bāngmáng?","Do you need a hand?"]]],["进来","jìn lai","to come in","",[["门开着，进来吧！","Mén kāi zhe, jìnlái ba!","The door's open, come on in!"]]],["颜色","yán sè","color","",[["你喜欢什么颜色？","Nǐ xǐhuan shénme yánsè?","What color do you like?"]]],["高中","gāo zhōng","senior high school","",[["我弟弟今年上高中。","Wǒ dìdi jīnnián shàng gāozhōng.","My younger brother starts high school this year."]]],["考","kǎo","to take (an exam), test","",[["你这次考得怎么样？","Nǐ zhè cì kǎo de zěnmeyàng?","How did you do on the exam this time?"]]],["上去","shàng qu","to go up","",[["电梯坏了，我们走上去吧。","Diàntī huài le, wǒmen zǒu shàngqù ba.","The elevator's broken, let's walk up."]]],["红色","hóng sè","red","",[["我想买那件红色的。","Wǒ xiǎng mǎi nà jiàn hóngsè de.","I'd like to buy the red one."]]],["游","yóu","to swim; to tour","Mostly in compounds: 游泳 (swim), 旅游 (travel).",[["他游得比我快多了。","Tā yóu de bǐ wǒ kuài duō le.","He swims much faster than me."]]],["一会儿","yí huì r","a moment, a little while","Standard yí huì r; many speakers say yì huǐ r.",[["我们休息一会儿吧。","Wǒmen xiūxi yíhuìr ba.","Let's take a short break."]]],["机场","jī chǎng","airport","",[["我们几点去机场？","Wǒmen jǐ diǎn qù jīchǎng?","What time are we going to the airport?"]]],["踢","tī","to kick; to play (football)","",[["你喜欢踢足球吗？","Nǐ xǐhuan tī zúqiú ma?","Do you like playing football?"]]],["舒服","shū fu","comfortable; feeling well","不舒服 = feeling unwell (sick), not just uncomfortable.",[["我今天有点儿不舒服。","Wǒ jīntiān yǒudiǎnr bù shūfu.","I'm not feeling well today."]]],["黑色","hēi sè","black","",[["黑色的那个是我的。","Hēisè de nàge shì wǒ de.","The black one is mine."]]],["绿色","lǜ sè","green","",[["我的车是绿色的。","Wǒ de chē shì lǜsè de.","My car is green."]]],["网上","wǎng shàng","online","",[["这个在网上买更便宜。","Zhège zài wǎngshàng mǎi gèng piányi.","This is cheaper to buy online."]]],["旅游","lǚ yóu","to travel (for fun); tourism","Say 去北京旅游, not 旅游北京.",[["放假的时候我想去旅游。","Fàngjià de shíhou wǒ xiǎng qù lǚyóu.","I want to travel during the holidays."]]],["足球","zú qiú","football, soccer","",[["晚上我们一起看足球吧！","Wǎnshang wǒmen yìqǐ kàn zúqiú ba!","Let's watch football together tonight!"]]],["白色","bái sè","white","",[["白色的衣服不好洗。","Báisè de yīfu bù hǎo xǐ.","White clothes are hard to wash."]]],["题","tí","question, problem (in an exam)","Measure word 道: 一道题.",[["这道题怎么做？","Zhè dào tí zěnme zuò?","How do you solve this problem?"]]],["门口","mén kǒu","entrance, doorway","",[["我在门口等你。","Wǒ zài ménkǒu děng nǐ.","I'll wait for you at the entrance."]]],["不好意思","bù hǎo yì si","sorry, excuse me; embarrassed","Lighter than 对不起; also 'excuse me' to get attention.",[["不好意思，我来晚了。","Bùhǎoyìsi, wǒ lái wǎn le.","Sorry I'm late."]]],["奶奶","nǎi nai","grandma (father's mother)","Mother's mother is 外婆 (usual in Shanghai) or 姥姥.",[["我奶奶今年八十岁了。","Wǒ nǎinai jīnnián bā shí suì le.","My grandma is turning eighty this year."]]],["右边","yòu bian","right side","",[["超市在路的右边。","Chāoshì zài lù de yòubian.","The supermarket is on the right side of the road."]]],["有意思","yǒu yì si","interesting, fun","",[["这个电影很有意思。","Zhège diànyǐng hěn yǒuyìsi.","This movie is really interesting."]]],["出门","chū mén","to go out, leave home","",[["我每天八点出门。","Wǒ měi tiān bā diǎn chūmén.","I leave home at eight every day."]]],["地铁","dì tiě","subway, metro","",[["坐地铁去比打车快。","Zuò dìtiě qù bǐ dǎchē kuài.","Taking the metro is faster than a taxi."]]],["小时候","xiǎo shí hou","as a child, in childhood","",[["我小时候住在北京。","Wǒ xiǎoshíhou zhù zài Běijīng.","I lived in Beijing when I was little."]]],["爷爷","yé ye","grandpa (father's father)","Mother's father is 外公 (usual in Shanghai) or 姥爷.",[["爷爷每天早上去公园。","Yéye měi tiān zǎoshang qù gōngyuán.","Grandpa goes to the park every morning."]]],["上来","shàng lai","to come up","",[["你上来吧，我在三楼。","Nǐ shànglái ba, wǒ zài sān lóu.","Come on up, I'm on the third floor."]]],["姓","xìng","surname; to be surnamed","Reply 我姓王, never 我贵姓王.",[["您好，请问您贵姓？","Nín hǎo, qǐngwèn nín guì xìng?","Hello, may I ask your surname?"]]],["篮球","lán qiú","basketball","",[["他篮球打得很好。","Tā lánqiú dǎ de hěn hǎo.","He plays basketball really well."]]],["游泳","yóu yǒng","to swim; swimming","",[["夏天我经常去游泳。","Xiàtiān wǒ jīngcháng qù yóuyǒng.","I often go swimming in summer."]]],["裤子","kù zi","trousers, pants","Measure word 条: 一条裤子.",[["这条裤子有点儿长。","Zhè tiáo kùzi yǒudiǎnr cháng.","These trousers are a bit long."]]],["跳舞","tiào wǔ","to dance","Verb-object word: repeat the verb before 得 (跳舞跳得好).",[["她跳舞跳得很好。","Tā tiàowǔ tiào de hěn hǎo.","She dances really well."]]],["阴","yīn","cloudy, overcast","",[["天阴了，可能要下雨。","Tiān yīn le, kěnéng yào xiàyǔ.","It's clouding over, it might rain."]]],["上网","shàng wǎng","to go online","",[["你家里能上网吗？","Nǐ jiālǐ néng shàngwǎng ma?","Can you get online at your place?"]]],["商场","shāng chǎng","shopping mall","",[["我们去商场买衣服吧。","Wǒmen qù shāngchǎng mǎi yīfu ba.","Let's go to the mall to buy clothes."]]],["外国","wài guó","foreign country; foreign","外国人 = foreigner; colloquially 老外.",[["这里有很多外国人。","Zhèli yǒu hěn duō wàiguó rén.","There are a lot of foreigners here."]]],["姓名","xìng míng","full name","Used on forms; in speech ask 你叫什么名字？",[["请在这儿写上你的姓名。","Qǐng zài zhèr xiě shàng nǐ de xìngmíng.","Please write your full name here."]]],["车站","chē zhàn","station; bus stop","",[["我去车站接你。","Wǒ qù chēzhàn jiē nǐ.","I'll pick you up at the station."]]],["走路","zǒu lù","to walk, go on foot","",[["我们走路去吧。","Wǒmen zǒulù qù ba.","Let's walk there."]]],["左边","zuǒ bian","left side","",[["左边那个人是谁？","Zuǒbian nàge rén shì shuí?","Who's that person on the left?"]]],["从小","cóng xiǎo","since childhood","",[["我从小在上海长大。","Wǒ cóngxiǎo zài Shànghǎi zhǎngdà.","I grew up in Shanghai."]]],["爱好","ài hào","hobby; to be keen on","",[["你有什么爱好？","Nǐ yǒu shénme àihào?","What are your hobbies?"]]],["教室","jiào shì","classroom","教 is jiào here, not jiāo.",[["教室里没有人。","Jiàoshì lǐ méiyǒu rén.","There's nobody in the classroom."]]],["快要","kuài yào","about to, soon","Needs 了 at the end: 快要…了.",[["快要下雨了，我们走吧。","Kuàiyào xiàyǔ le, wǒmen zǒu ba.","It's about to rain, let's go."]]],["门票","mén piào","entrance ticket","",[["门票多少钱一张？","Ménpiào duōshao qián yì zhāng?","How much is an entrance ticket?"]]],["机票","jī piào","plane ticket","",[["我已经买好机票了。","Wǒ yǐjīng mǎi hǎo jīpiào le.","I've already bought the plane ticket."]]],["手表","shǒu biǎo","wristwatch","Measure word 块: 一块手表.",[["这块手表是我爸爸送的。","Zhè kuài shǒubiǎo shì wǒ bàba sòng de.","My dad gave me this watch."]]],["出国","chū guó","to go abroad","",[["他明年想出国读书。","Tā míngnián xiǎng chūguó dúshū.","He wants to go abroad to study next year."]]],["跑步","pǎo bù","to run, jog","",[["下班以后我喜欢去跑步。","Xiàbān yǐhòu wǒ xǐhuan qù pǎobù.","I like to go running after work."]]],["药店","yào diàn","pharmacy","",[["附近有药店吗？","Fùjìn yǒu yàodiàn ma?","Is there a pharmacy nearby?"]]],["晴","qíng","sunny, clear","",[["天晴了，我们出去走走吧。","Tiān qíng le, wǒmen chūqù zǒu zǒu ba.","The sky's cleared up, let's go out for a walk."]]],["洗手间","xǐ shǒu jiān","restroom, toilet","",[["请问，洗手间在哪儿？","Qǐngwèn, xǐshǒujiān zài nǎr?","Excuse me, where's the restroom?"]]],["开学","kāi xué","(of school) to start term","",[["我们九月一号开学。","Wǒmen jiǔ yuè yī hào kāixué.","School starts on September 1st."]]],["个子","gè zi","height, build","",[["你弟弟个子真高！","Nǐ dìdi gèzi zhēn gāo!","Your little brother is really tall!"]]],["没意思","méi yì si","boring","",[["这个游戏真没意思。","Zhège yóuxì zhēn méiyìsi.","This game is really boring."]]],["书包","shū bāo","schoolbag","",[["我的书包里有很多书。","Wǒ de shūbāo lǐ yǒu hěn duō shū.","There are a lot of books in my schoolbag."]]],["本子","běn zi","notebook","",[["请把这个词写在本子上。","Qǐng bǎ zhège cí xiě zài běnzi shàng.","Please write this word in your notebook."]]],["过年","guò nián","to celebrate Chinese New Year","Means the Spring Festival, not January 1st.",[["过年你回家吗？","Guònián nǐ huíjiā ma?","Are you going home for Chinese New Year?"]]],["绿茶","lǜ chá","green tea","",[["来一杯绿茶，谢谢！","Lái yì bēi lǜchá, xièxie!","A green tea, please!"]]],["打车","dǎ chē","to take a taxi","Also used for ride-hailing apps; 开车 = to drive yourself.",[["太晚了，我们打车回家吧。","Tài wǎn le, wǒmen dǎchē huíjiā ba.","It's late, let's take a taxi home."]]],["饭馆","fàn guǎn","restaurant","饭馆 is a casual restaurant; 饭店 can also mean hotel.",[["这家饭馆的菜很好吃。","Zhè jiā fànguǎn de cài hěn hǎochī.","The food at this restaurant is great."]]],["女孩儿","nǚ hái r","girl","In the south, incl. Shanghai, people usually say 女孩 without 儿.",[["那个女孩儿是你妹妹吗？","Nàge nǚháir shì nǐ mèimei ma?","Is that girl your younger sister?"]]],["奶茶","nǎi chá","milk tea, bubble tea","",[["我们去买奶茶吧！","Wǒmen qù mǎi nǎichá ba!","Let's go get bubble tea!"]]],["红茶","hóng chá","black tea","Literally 'red tea', but it's what English calls black tea.",[["这是红茶还是绿茶？","Zhè shì hóngchá háishi lǜchá?","Is this black tea or green tea?"]]],["小孩儿","xiǎo hái r","child, kid","In the south, incl. Shanghai, people usually say 小孩 without 儿.",[["这个小孩儿真可爱！","Zhège xiǎoháir zhēn kě'ài!","This kid is so cute!"]]],["公交车","gōng jiāo chē","bus","",[["这路公交车到机场吗？","Zhè lù gōngjiāochē dào jīchǎng ma?","Does this bus go to the airport?"]]],["男孩儿","nán hái r","boy","In the south, incl. Shanghai, people usually say 男孩 without 儿.",[["他们家有两个男孩儿。","Tāmen jiā yǒu liǎng gè nánháir.","They have two boys in their family."]]]]},{"id":"survival","name":"Survival phrases","zh":"生存用语","group":"Topics","desc":"Greetings, thanks, “I don’t understand” and the phrases you need on day one.","words":[["你好","nǐ hǎo","hello","",[["你好，我想问一下。","Nǐ hǎo, wǒ xiǎng wèn yíxià.","Hello, can I ask you something?"]]],["谢谢","xiè xie","thank you; thanks","",[["谢谢，你人真好！","Xièxie, nǐ rén zhēn hǎo!","Thanks, that's really kind of you!"]]],["不客气","bú kè qi","you're welcome","",[["不客气，应该的。","Búkèqi, yīnggāi de.","You're welcome, it's no trouble."]]],["不好意思","bù hǎo yì si","excuse me; sorry (minor)","The everyday \"sorry/excuse me\" for small things; 对不起 is a heavier apology.",[["不好意思，让一下。","Bùhǎoyìsi, ràng yíxià.","Excuse me, coming through."]]],["对不起","duì bu qǐ","sorry; I apologize","",[["对不起，我来晚了。","Duìbuqǐ, wǒ lái wǎn le.","Sorry I'm late."]]],["没关系","méi guān xi","it doesn't matter; never mind","",[["没关系，别担心。","Méiguānxi, bié dānxīn.","It's fine, don't worry."]]],["没事","méi shì","it's OK; no worries","",[["没事，我自己来。","Méi shì, wǒ zìjǐ lái.","It's fine, I'll do it myself."]]],["再见","zài jiàn","goodbye","",[["那我先走了，再见！","Nà wǒ xiān zǒu le, zàijiàn!","I'll be off then, bye!"]]],["请","qǐng","please; to invite","Used to invite or offer; for favors, 麻烦你… or 能…吗？ sounds more natural.",[["请坐，喝杯茶吧。","Qǐngzuò, hē bēi chá ba.","Please sit down and have some tea."]]],["请问","qǐng wèn","excuse me, may I ask…","",[["请问，地铁站在哪里？","Qǐngwèn, dìtiězhàn zài nǎli?","Excuse me, where's the metro station?"]]],["我听不懂","wǒ tīng bu dǒng","I don't understand (what's said)","听不懂 = can't follow by ear; 看不懂 = can't read it.",[["我听不懂上海话。","Wǒ tīng bu dǒng Shànghǎihuà.","I don't understand Shanghainese."]]],["再说一遍","zài shuō yí biàn","say it again","",[["请再说一遍，好吗？","Qǐng zàishuō yí biàn, hǎo ma?","Could you say that again, please?"]]],["慢一点","màn yì diǎn","a bit slower","",[["你能说慢一点吗？","Nǐ néng shuō màn yì diǎn ma?","Could you speak a bit slower?"]]],["你会说英语吗","nǐ huì shuō Yīng yǔ ma","do you speak English?","",[["不好意思，你会说英语吗？","Bùhǎoyìsi, nǐ huì shuō Yīngyǔ ma?","Sorry, do you speak English?"]]],["什么意思","shén me yì si","what does it mean?","",[["这个字是什么意思？","Zhège zì shì shénme yìsi?","What does this character mean?"]]],["怎么说","zěn me shuō","how do you say…?","",[["这个用中文怎么说？","Zhège yòng Zhōngwén zěnme shuō?","How do you say this in Chinese?"]]],["对","duì","right; correct; yes","No single word for \"yes\": say 对 or 是, or repeat the verb (有, 要, 可以).",[["对，就是这个。","Duì, jiùshì zhège.","Yes, that's the one."]]],["不是","bú shì","no; it's not","",[["不是这个，是那个。","Bú shì zhège, shì nàge.","Not this one, that one."]]],["好的","hǎo de","OK; sure","",[["好的，我知道了。","Hǎode, wǒ zhīdao le.","OK, got it."]]],["可以","kě yǐ","can; may; OK","可以 = allowed or possible; 会 = know how to (会说中文).",[["这里可以拍照吗？","Zhèli kěyǐ pāizhào ma?","Can I take photos here?"]]],["不用了","bú yòng le","no need; no thanks","",[["不用了，谢谢你。","Búyòng le, xièxie nǐ.","No need, thank you."]]],["没问题","méi wèn tí","no problem","",[["没问题，交给我吧。","Méi wèntí, jiāogěi wǒ ba.","No problem, leave it to me."]]],["这个","zhè ge","this; this one","Often pronounced zhèi ge in speech.",[["这个是什么？","Zhège shì shénme?","What's this?"]]],["多少钱","duō shao qián","how much (money)?","",[["老板，这个多少钱？","Lǎobǎn, zhège duōshao qián?","Excuse me, how much is this?"]]],["可以扫码吗","kě yǐ sǎo mǎ ma","can I pay by scanning (QR)?","",[["我没有现金，可以扫码吗？","Wǒ méiyǒu xiànjīn, kěyǐ sǎo mǎ ma?","I don't have cash. Can I scan to pay?"]]],["厕所在哪里","cè suǒ zài nǎ lǐ","where's the toilet?","Signs say 洗手间 or 卫生间. Northerners say 哪儿 (nǎr); Shanghai says 哪里.",[["不好意思，厕所在哪里？","Bùhǎoyìsi, cèsuǒ zài nǎli?","Excuse me, where's the toilet?"]]],["等一下","děng yí xià","wait a moment","",[["等一下，我马上来！","Děng yíxià, wǒ mǎshàng lái!","Hold on, I'm coming!"]]],["有没有","yǒu méi yǒu","is there…?; do you have…?","",[["附近有没有便利店？","Fùjìn yǒuméiyǒu biànlìdiàn?","Is there a convenience store nearby?"]]],["没有了","méi yǒu le","none left; sold out","",[["这个没有了，换一个吧。","Zhège méiyǒu le, huàn yí gè ba.","We're out of this one, pick another."]]],["我不知道","wǒ bù zhī dào","I don't know","",[["我不知道，你问问他吧。","Wǒ bù zhīdao, nǐ wèn wèn tā ba.","I don't know, try asking him."]]],["一点点","yì diǎn diǎn","a little bit","",[["我只会说一点点中文。","Wǒ zhǐ huì shuō yìdiǎndiǎn Zhōngwén.","I only speak a little Chinese."]]],["麻烦你","má fan nǐ","sorry to bother you; could you…","",[["麻烦你开一下门。","Máfan nǐ kāi yíxià mén.","Could you open the door, please?"]]],["帮忙","bāng máng","to help; to do a favor","Separable: 帮个忙, 帮我一个忙. Say 帮我, never 帮忙我.",[["能帮忙拍张照吗？","Néng bāngmáng pāi zhāng zhào ma?","Could you help take a photo?"]]],["我迷路了","wǒ mí lù le","I'm lost","",[["我迷路了，这是哪里？","Wǒ mílù le, zhè shì nǎli?","I'm lost. Where is this?"]]],["我不舒服","wǒ bù shū fu","I don't feel well","",[["我不舒服，想去医院。","Wǒ bù shūfu, xiǎng qù yīyuàn.","I don't feel well. I want to go to a hospital."]]],["救命","jiù mìng","help! (emergency)","",[["救命啊！快来人！","Jiùmìng a! Kuài lái rén!","Help! Somebody come quick!"]]],["报警","bào jǐng","to call the police","Emergency numbers: 110 police, 120 ambulance, 119 fire.",[["我要报警，手机被偷了。","Wǒ yào bàojǐng, shǒujī bèi tōu le.","I want to call the police, my phone was stolen."]]],["小心","xiǎo xīn","careful!; to be careful","",[["小心，地上很滑！","Xiǎoxīn, dìshang hěn huá!","Careful, the floor is slippery!"]]],["充电宝","chōng diàn bǎo","power bank","",[["哪里可以借充电宝？","Nǎli kěyǐ jiè chōngdiàn bǎo?","Where can I rent a power bank?"]]],["加微信","jiā Wēi xìn","to add (someone) on WeChat","Also 加个微信. 我扫你 / 你扫我 = who scans whose QR code.",[["方便加微信吗？","Fāngbiàn jiā Wēixìn ma?","Is it OK if we add each other on WeChat?"]]],["哪国人","nǎ guó rén","which country (are you from)?","",[["你是哪国人？来旅游吗？","Nǐ shì nǎ guó rén? Lái lǚyóu ma?","Where are you from? Here on holiday?"]]],["您好","nín hǎo","hello (polite)","",[["您好，请问需要什么？","Nín hǎo, qǐngwèn xūyào shénme?","Hello, what can I get you?"]]]]},{"id":"food","name":"Food and ordering","zh":"点菜","group":"Topics","desc":"Ordering, dishes, tastes, dietary needs and paying the bill.","words":[["几位","jǐ wèi","how many people? (asked by host)","",[["你好，请问几位？","Nǐ hǎo, qǐngwèn jǐ wèi?","Hi, how many of you?"]]],["菜单","cài dān","menu","",[["麻烦给我看一下菜单。","Máfan gěi wǒ kàn yíxià càidān.","Could I see the menu, please?"]]],["扫码点餐","sǎo mǎ diǎn cān","scan the QR code to order","",[["这里是扫码点餐的。","Zhèli shì sǎo mǎ diǎn cān de.","Here you order by scanning the QR code."]]],["服务员","fú wù yuán","waiter; waitress","Calling out 服务员 to get attention is normal, not rude.",[["服务员，再来一碗米饭！","Fúwùyuán, zài lái yì wǎn mǐfàn!","Excuse me, another bowl of rice, please!"]]],["点菜","diǎn cài","to order (food)","",[["你好，我们要点菜。","Nǐ hǎo, wǒmen yàodiǎn cài.","Hi, we'd like to order."]]],["来一份","lái yí fèn","one portion of…, please","来 is the casual way to order: 来一碗面, 来两瓶啤酒.",[["来一份宫保鸡丁。","Lái yí fèn gōng bǎo jī dīng.","One kung pao chicken, please."]]],["推荐","tuī jiàn","to recommend","",[["有什么推荐的吗？","Yǒu shénme tuījiàn de ma?","Anything you'd recommend?"]]],["就这些","jiù zhè xiē","that's all","",[["就这些吧，不够再点。","Jiù zhèxiē ba, búgòu zài diǎn.","That's all for now, we'll order more if needed."]]],["买单","mǎi dān","to pay the bill; check, please","Also 结账 (jié zhàng). At many places you pay at the counter instead.",[["吃好了，买单吧。","Chī hǎo le, mǎi dān ba.","We're done, let's get the bill."]]],["打包","dǎ bāo","to pack up (leftovers or to go)","",[["吃不完，帮我打包吧。","Chī bù wán, bāng wǒ dǎbāo ba.","We can't finish it, please pack it up."]]],["带走","dài zǒu","to take away; to go","Also asked as 堂食还是外带？ (dine in or take out?)",[["在这儿吃还是带走？","Zài zhèr chī háishi dài zǒu?","For here or to go?"]]],["外卖","wài mài","food delivery; takeout","",[["今天点外卖吧。","Jīntiān diǎn wàimài ba.","Let's order delivery today."]]],["辣","là","spicy; hot","",[["这个菜辣不辣？","Zhège cài là bu là?","Is this dish spicy?"]]],["不要辣","bú yào là","no chili, please","",[["这个不要辣，可以吗？","Zhège búyào là, kěyǐ ma?","Can you make this one not spicy?"]]],["微辣","wēi là","mildly spicy","Even 微辣 can be very hot in Sichuan or Hunan restaurants.",[["来个微辣的就行。","Lái gè wēi là de jiù xíng.","Just mildly spicy, please."]]],["不要香菜","bú yào xiāng cài","no coriander (cilantro), please","",[["不要香菜，也不要葱。","Búyào xiāng cài, yě búyào cōng.","No coriander and no scallions."]]],["少油","shǎo yóu","less oil","",[["少油少盐，谢谢。","Shǎo yóu shǎo yán, xièxie.","Less oil and less salt, please."]]],["我吃素","wǒ chī sù","I'm vegetarian","Veggie dishes may still contain minced meat or lard; ask 有没有放肉？",[["我吃素，有素菜吗？","Wǒ chī sù, yǒu sù cài ma?","I'm vegetarian. Do you have meat-free dishes?"]]],["过敏","guò mǐn","to be allergic; allergy","Pattern: 对 + thing + 过敏.",[["我对花生过敏。","Wǒ duì huāshēng guòmǐn.","I'm allergic to peanuts."]]],["菜","cài","dish (of food); vegetable","Means any dish, meat included, not only vegetables.",[["这个菜叫什么？","Zhège cài jiào shénme?","What's this dish called?"]]],["米饭","mǐ fàn","cooked rice","",[["米饭要另外点吗？","Mǐfàn yào lìngwài diǎn ma?","Do we order rice separately?"]]],["面条","miàn tiáo","noodles","",[["中午吃碗面条吧。","Zhōngwǔ chī wǎn miàntiáo ba.","Let's have a bowl of noodles for lunch."]]],["饺子","jiǎo zi","dumplings","Often sold by weight: 一两 = 50 g. Say 二两, not 两两.",[["我要二两饺子。","Wǒ yào èr liǎng jiǎozi.","Two liang (100 g) of dumplings, please."]]],["包子","bāo zi","steamed bun (with filling)","",[["来两个肉包子。","Lái liǎng gè ròu bāozi.","Two meat buns, please."]]],["牛肉","niú ròu","beef","",[["来一碗牛肉面。","Lái yì wǎn niú ròu miàn.","A bowl of beef noodles, please."]]],["猪肉","zhū ròu","pork","Plain 肉 in a dish name usually means pork.",[["我不吃猪肉。","Wǒ bù chī zhū ròu.","I don't eat pork."]]],["鸡肉","jī ròu","chicken (meat)","",[["这个是鸡肉还是牛肉？","Zhège shì jī ròu háishi niú ròu?","Is this chicken or beef?"]]],["鱼","yú","fish","",[["这个鱼刺多不多？","Zhège yú cì duō bu duō?","Does this fish have a lot of bones?"]]],["青菜","qīng cài","leafy greens; bok choy","",[["再炒一个青菜吧。","Zài chǎo yí gè qīng cài ba.","Let's also get some stir-fried greens."]]],["汤","tāng","soup","Soup is 喝 (drunk), not 吃: 喝汤.",[["这个汤很好喝。","Zhège tāng hěn hǎo hē.","This soup is really good."]]],["好吃","hǎo chī","tasty; delicious","For drinks, say 好喝.",[["这个菜真好吃！","Zhège cài zhēn hǎochī!","This dish is really tasty!"]]],["筷子","kuài zi","chopsticks","Measure word: 一双 (a pair).",[["能再给我一双筷子吗？","Néng zài gěi wǒ yì shuāng kuàizi ma?","Could I have another pair of chopsticks?"]]],["勺子","sháo zi","spoon","",[["麻烦拿个勺子。","Máfan ná gè sháozi.","Could you bring a spoon, please?"]]],["纸巾","zhǐ jīn","tissues; paper napkins","",[["桌上没有纸巾了。","Zhuō shàng méiyǒu zhǐ jīn le.","There are no napkins left on the table."]]],["热水","rè shuǐ","hot water","",[["给我一杯热水吧。","Gěi wǒ yì bēi rèshuǐ ba.","Can I have a cup of hot water?"]]],["冰的","bīng de","cold (iced) one","Drinks often come at room temperature (常温) unless you ask for 冰的.",[["啤酒要冰的。","Píjiǔ yào bīng de.","I'd like the beer cold."]]],["啤酒","pí jiǔ","beer","Say 两瓶, not 二瓶: use 两 before measure words.",[["来两瓶啤酒。","Lái liǎng píng píjiǔ.","Two bottles of beer, please."]]],["茶","chá","tea","",[["这里的茶是免费的吗？","Zhèli de chá shì miǎnfèi de ma?","Is the tea here free?"]]],["咖啡","kā fēi","coffee","",[["我要一杯冰咖啡。","Wǒ yào yì bēi bīng kāfēi.","An iced coffee, please."]]],["奶茶","nǎi chá","milk tea; bubble tea","",[["一起去喝奶茶吧！","Yìqǐ qù hē nǎichá ba!","Let's go get bubble tea!"]]],["少糖","shǎo táng","less sugar","Tea shops ask sweetness: 全糖 (full), 半糖 (half), 三分糖 (30%), 无糖 (none).",[["我要少糖的，谢谢。","Wǒ yào shǎo táng de, xièxie.","Less sugar for me, thanks."]]],["吃饭","chī fàn","to eat (a meal)","Means \"have a meal\" in general, not just rice.",[["我们去哪里吃饭？","Wǒmen qù nǎli chīfàn?","Where shall we go to eat?"]]],["吃饱了","chī bǎo le","I'm full","",[["我吃饱了，你们慢慢吃。","Wǒ chī bǎo le, nǐmen mànmàn chī.","I'm full. Take your time, everyone."]]],["够","gòu","enough","",[["三个人，四个菜够吗？","Sān gè rén, sì gè cài gòu ma?","Are four dishes enough for three people?"]]],["上菜","shàng cài","to serve the food","",[["能快点上菜吗？","Néng kuài diǎn shàng cài ma?","Could the food come a bit faster?"]]],["老板","lǎo bǎn","boss; how to address a vendor","",[["老板，再来两串！","Lǎobǎn, zài lái liǎng chuàn!","Boss, two more skewers!"]]],["清淡","qīng dàn","light (not oily or spicy)","",[["我想吃点清淡的。","Wǒ xiǎng chī diǎn qīngdàn de.","I feel like something light."]]],["甜","tián","sweet","",[["上海菜有点甜。","Shànghǎi cài yǒu diǎn tián.","Shanghai food is a bit sweet."]]],["干杯","gān bēi","cheers!","Can mean \"empty your glass\"; 随意 means \"drink as much as you like\".",[["来，大家干杯！","Lái, dàjiā gānbēi!","Come on, everyone, cheers!"]]],["火锅","huǒ guō","hotpot","",[["今晚吃火锅吧！","Jīnwǎn chī huǒguō ba!","Let's have hotpot tonight!"]]],["烧烤","shāo kǎo","barbecue; grilled skewers","",[["楼下有家烧烤店。","Lóuxià yǒu jiā shāokǎo diàn.","There's a barbecue place downstairs."]]],["小笼包","xiǎo lóng bāo","soup dumplings (xiaolongbao)","",[["小笼包要趁热吃。","Xiǎo lóng bāo yào chèn rè chī.","Eat xiaolongbao while they're hot."]]]]},{"id":"transport","name":"Getting around","zh":"出行","group":"Topics","desc":"Metro, taxis and DiDi, directions, trains and the airport.","words":[["地铁","dì tiě","subway; metro","Vehicles take 坐 (坐地铁, 坐公交); bikes take 骑.",[["坐地铁去比较快。","Zuò dìtiě qù bǐjiào kuài.","It's quicker to take the metro."]]],["打车","dǎ chē","to take a taxi","",[["太晚了，我们打车吧。","Tài wǎn le, wǒmen dǎchē ba.","It's late, let's get a taxi."]]],["怎么走","zěn me zǒu","how do I get there?","",[["去外滩怎么走？","Qù Wàitān zěnme zǒu?","How do I get to the Bund?"]]],["左转","zuǒ zhuǎn","to turn left","",[["在下个路口左转。","Zài xià gè lùkǒu zuǒ zhuǎn.","Turn left at the next intersection."]]],["右转","yòu zhuǎn","to turn right","",[["过了红绿灯右转。","Guò le hóng lǜdēng yòu zhuǎn.","Turn right after the traffic lights."]]],["直走","zhí zǒu","to go straight","",[["直走两百米就到了。","Zhí zǒu liǎng bǎi mǐ jiù dào le.","Go straight 200 meters and you're there."]]],["师傅","shī fu","driver; master (polite address)","Polite way to address taxi drivers and tradespeople.",[["师傅，去火车站。","Shīfu, qù huǒchēzhàn.","To the train station, please."]]],["停一下","tíng yí xià","to stop (briefly)","",[["就在这里停一下吧。","Jiù zài zhèli tíng yíxià ba.","Just stop here, please."]]],["到了","dào le","we're here; arrived","",[["到了，就是这里。","Dào le, jiùshì zhèli.","We're here, this is the place."]]],["出口","chū kǒu","exit","Shanghai metro exits are numbered (4号口); Beijing uses letters (A口).",[["我在四号出口等你。","Wǒ zài sì hào chūkǒu děng nǐ.","I'll wait for you at Exit 4."]]],["站","zhàn","station; stop","",[["坐三站就到了。","Zuò sān zhàn jiù dào le.","It's only three stops."]]],["几号线","jǐ hào xiàn","which (metro) line?","",[["去机场坐几号线？","Qù jīchǎng zuò jǐ hào xiàn?","Which line goes to the airport?"]]],["换乘","huàn chéng","to transfer (lines)","",[["在这站换乘二号线。","Zài zhè zhàn huàn chéng èr hào xiàn.","Change to Line 2 at this stop."]]],["多远","duō yuǎn","how far?","Distance uses 离: A 离 B 很近.",[["火车站离这里多远？","Huǒchēzhàn lí zhèli duō yuǎn?","How far is the train station from here?"]]],["多久","duō jiǔ","how long (time)?","",[["坐地铁要多久？","Zuò dìtiě yào duōjiǔ?","How long does it take by metro?"]]],["近","jìn","near; close","",[["很近，走路五分钟。","Hěn jìn, zǒulù wǔ fēnzhōng.","It's close, five minutes on foot."]]],["走路","zǒu lù","to walk; on foot","",[["不远，走路过去吧。","Bù yuǎn, zǒulù guòqù ba.","It's not far, let's walk."]]],["附近","fù jìn","nearby","",[["附近有地铁站吗？","Fùjìn yǒu dìtiězhàn ma?","Is there a metro station nearby?"]]],["左边","zuǒ bian","left side","",[["银行在你左边。","Yínháng zài nǐ zuǒbian.","The bank is on your left."]]],["右边","yòu bian","right side","",[["厕所在右边。","Cèsuǒ zài yòubian.","The restroom is on the right."]]],["对面","duì miàn","opposite; across the street","",[["就在马路对面。","Jiù zài mǎlù duìmiàn.","It's right across the street."]]],["旁边","páng biān","next to; beside","",[["便利店就在旁边。","Biànlìdiàn jiù zài pángbiān.","The convenience store is right next door."]]],["滴滴","Dī dī","Didi (ride-hailing app)","",[["我用滴滴叫个车。","Wǒ yòng Dīdī jiào gè chē.","I'll call a car on Didi."]]],["出租车","chū zū chē","taxi","",[["出租车在哪里排队？","Chūzūchē zài nǎli páiduì?","Where's the taxi line?"]]],["地址","dì zhǐ","address","",[["这是地址，你看一下。","Zhè shì dìzhǐ, nǐ kàn yíxià.","Here's the address, take a look."]]],["公交车","gōng jiāo chē","bus","Bus routes use 路: 坐71路 = take bus 71.",[["这路公交车到外滩吗？","Zhè lù gōngjiāochē dào Wàitān ma?","Does this bus go to the Bund?"]]],["上车","shàng chē","to get on (a vehicle)","",[["我上车了，二十分钟到。","Wǒ shàngchē le, èr shí fēnzhōng dào.","I'm in the car, there in 20 minutes."]]],["下车","xià chē","to get off (a vehicle)","",[["我在下一站下车。","Wǒ zài xià yí zhàn xiàchē.","I'm getting off at the next stop."]]],["下一站","xià yí zhàn","next stop","",[["下一站是人民广场。","Xià yí zhàn shì Rénmínguǎngchǎng.","The next stop is People's Square."]]],["乘车码","chéng chē mǎ","transit QR code","Found in Alipay or WeChat; 刷 = to swipe or scan.",[["刷乘车码就能进站。","Shuā chéngchē mǎ jiù néng jìn zhàn.","Just scan the transit QR code to get in."]]],["安检","ān jiǎn","security check","",[["进地铁要过安检。","Jìn dìtiě yào guò ānjiǎn.","You go through security to enter the metro."]]],["火车站","huǒ chē zhàn","train station","Shanghai has several (上海站, 上海南站, 虹桥站); check your ticket.",[["去哪个火车站？","Qù nǎge huǒchēzhàn?","Which train station?"]]],["高铁","gāo tiě","high-speed rail","",[["去杭州坐高铁吧。","Qù Hángzhōu zuò gāotiě ba.","Take the high-speed train to Hangzhou."]]],["机场","jī chǎng","airport","Shanghai has two airports: 浦东 (PVG) and 虹桥 (SHA).",[["我要去浦东机场。","Wǒ yào qù Pǔdōng jīchǎng.","I'm going to Pudong Airport."]]],["护照","hù zhào","passport","",[["坐高铁要带护照。","Zuò gāotiě yào dài hùzhào.","You need your passport for the high-speed train."]]],["买票","mǎi piào","to buy a ticket","",[["在哪里买票？","Zài nǎli mǎi piào?","Where do I buy a ticket?"]]],["航班","háng bān","flight","",[["我的航班延误了。","Wǒ de hángbān yánwù le.","My flight is delayed."]]],["座位","zuò wèi","seat","",[["这个座位有人吗？","Zhège zuòwèi yǒurén ma?","Is this seat taken?"]]],["堵车","dǔ chē","traffic jam; to be jammed","",[["现在堵车，坐地铁吧。","Xiànzài dǔchē, zuò dìtiě ba.","Traffic's jammed, let's take the metro."]]],["共享单车","gòng xiǎng dān chē","shared bike","",[["骑共享单车去吧。","Qí gòngxiǎng dān chē qù ba.","Let's ride shared bikes there."]]],["行李","xíng li","luggage","",[["行李太多了，打车吧。","Xíngli tài duō le, dǎchē ba.","Too much luggage, let's take a taxi."]]],["末班车","mò bān chē","last train; last bus","",[["末班车是几点？","Mò bān chē shì jǐ diǎn?","When's the last train?"]]]]},{"id":"shopping","name":"Shopping and money","zh":"购物","group":"Topics","desc":"Prices, bargaining, sizes, paying with your phone and returns.","words":[["一共","yí gòng","in total; altogether","",[["一共多少钱？","Yígòng duōshao qián?","How much is it altogether?"]]],["块","kuài","yuan (spoken); piece","Spoken for 元 (written). 毛 = 0.1 yuan, written 角.",[["一杯咖啡三十块。","Yì bēi kāfēi sān shí kuài.","A coffee is thirty kuai."]]],["两","liǎng","two (before measure words)","Use 两 before measure words (两块, 两个); 二 in numbers (十二, 二十).",[["两块钱一个。","Liǎng kuài qián yí gè.","Two kuai each."]]],["太贵了","tài guì le","too expensive","",[["太贵了，便宜点吧。","Tài guì le, piányi diǎn ba.","That's too pricey, come down a bit."]]],["便宜一点","pián yi yì diǎn","a bit cheaper","Bargain at markets and stalls, not in malls or chain stores.",[["能便宜一点吗？","Néng piányi yì diǎn ma?","Can you go a bit cheaper?"]]],["最低","zuì dī","lowest","",[["最低多少钱？","Zuì dī duōshao qián?","What's your lowest price?"]]],["不买了","bù mǎi le","I won't buy it then","",[["那算了，不买了。","Nà suànle, bù mǎi le.","Never mind, I'll leave it."]]],["怎么卖","zěn me mài","how much is it? (price per unit)","卖 mài (sell) vs 买 mǎi (buy): only the tone differs.",[["苹果怎么卖？","Píngguǒ zěnme mài?","How much are the apples?"]]],["斤","jīn","jin (500 g)","Produce prices are usually per 斤 (500 g), not per kilo.",[["西瓜多少钱一斤？","Xīguā duōshao qián yì jīn?","How much is watermelon per jin?"]]],["要","yào","to want; to take","",[["这个我要两个。","Zhège wǒ yào liǎng gè.","I'll take two of these."]]],["现金","xiàn jīn","cash","",[["现在很少有人用现金。","Xiànzài hěn shǎo yǒurén yòng xiànjīn.","Hardly anyone uses cash now."]]],["微信支付","Wēi xìn zhī fù","WeChat Pay","",[["可以用微信支付吗？","Kěyǐ yòng Wēixìn zhīfù ma?","Can I use WeChat Pay?"]]],["支付宝","Zhī fù bǎo","Alipay","",[["我用支付宝付吧。","Wǒ yòng Zhīfùbǎo fù ba.","I'll pay with Alipay."]]],["刷卡","shuā kǎ","to pay by card","Small shops rarely take foreign cards; link yours to Alipay or WeChat.",[["这里可以刷卡吗？","Zhèli kěyǐ shuā kǎ ma?","Can I pay by card here?"]]],["零钱","líng qián","small change","",[["不好意思，我没有零钱。","Bùhǎoyìsi, wǒ méiyǒu língqián.","Sorry, I don't have any change."]]],["找钱","zhǎo qián","to give change","",[["不用找钱了。","Búyòng zhǎo qián le.","Keep the change."]]],["小票","xiǎo piào","receipt (till slip)","",[["小票要不要？","Xiǎo piào yào buyào?","Do you want the receipt?"]]],["发票","fā piào","official invoice (fapiao)","Official tax invoice for expense claims, not the same as a receipt (小票).",[["能开张发票吗？","Néng kāizhāng fāpiào ma?","Can you give me a fapiao?"]]],["袋子","dài zi","bag","Bags usually cost extra; say 不用 if you brought your own.",[["需要袋子吗？","Xūyào dài zi ma?","Do you need a bag?"]]],["便利店","biàn lì diàn","convenience store","",[["楼下就有便利店。","Lóuxià jiù yǒu biànlìdiàn.","There's a convenience store downstairs."]]],["超市","chāo shì","supermarket","",[["我去超市买点东西。","Wǒ qù chāoshì mǎi diǎn dōngxi.","I'm going to the supermarket to get a few things."]]],["随便看看","suí biàn kàn kan","just looking around","",[["不用了，我随便看看。","Búyòng le, wǒ suíbiàn kàn kan.","No thanks, I'm just looking."]]],["试一下","shì yí xià","to try (it) on; to try","",[["我能试一下吗？","Wǒ néng shì yíxià ma?","Can I try it on?"]]],["试衣间","shì yī jiān","fitting room","",[["试衣间在哪里？","Shì yī jiān zài nǎli?","Where's the fitting room?"]]],["合适","hé shì","to fit; suitable","",[["这件不太合适。","Zhè jiàn bútài héshì.","This one doesn't quite fit."]]],["大号","dà hào","large size","Chinese sizes run small; you may need one or two sizes up.",[["这件有大号的吗？","Zhè jiàn yǒu dà hào de ma?","Does this come in large?"]]],["码","mǎ","size (shoes, clothes); code","",[["这双鞋有四十二码吗？","Zhè shuāng xié yǒu sì shí èr mǎ ma?","Do these shoes come in a 42?"]]],["颜色","yán sè","color","",[["有别的颜色吗？","Yǒu biéde yánsè ma?","Do you have other colors?"]]],["黑色","hēi sè","black","",[["我想要黑色的。","Wǒ xiǎng yào hēisè de.","I'd like a black one."]]],["白色","bái sè","white","",[["白色的容易脏。","Báisè de róngyì zāng.","White gets dirty easily."]]],["打折","dǎ zhé","to give a discount","八折 means you pay 80%, i.e. 20% off, not 80% off.",[["这个打折吗？打几折？","Zhège dǎzhé ma? Dǎ jǐ zhé?","Is this on sale? How much off?"]]],["换","huàn","to exchange; to change","",[["颜色不喜欢，能换吗？","Yánsè bù xǐhuan, néng huàn ma?","I don't like the color. Can I exchange it?"]]],["退货","tuì huò","to return (goods)","",[["这个可以退货吗？","Zhège kěyǐ tuì huò ma?","Can I return this?"]]],["会员","huì yuán","member (loyalty program)","",[["请问有会员吗？","Qǐngwèn yǒu huìyuán ma?","Are you a member?"]]],["快递","kuài dì","courier; parcel delivery","",[["我的快递到了。","Wǒ de kuàidì dào le.","My package has arrived."]]],["关门","guān mén","to close (for the day)","",[["你们几点关门？","Nǐmen jǐ diǎn guān mén?","What time do you close?"]]],["矿泉水","kuàng quán shuǐ","mineral water","",[["来一瓶矿泉水。","Lái yì píng kuàngquánshuǐ.","A bottle of water, please."]]],["手机卡","shǒu jī kǎ","SIM card","You need your passport to get one.",[["在哪里办手机卡？","Zài nǎli bàn shǒujī kǎ?","Where can I get a SIM card?"]]]]},{"id":"dailylife","name":"Daily life in China","zh":"日常生活","group":"Topics","desc":"Apps, deliveries, your apartment, the bank and everyday errands.","words":[["微信","Wēi xìn","WeChat","",[["你有微信吗？","Nǐ yǒu Wēixìn ma?","Do you have WeChat?"]]],["手机","shǒu jī","mobile phone","",[["手机快没电了。","Shǒujī kuài méi diàn le.","My phone's almost dead."]]],["手机号","shǒu jī hào","mobile number","In phone numbers 1 is usually read yāo, not yī.",[["你的手机号是多少？","Nǐ de shǒujī hào shì duōshao?","What's your mobile number?"]]],["扫码","sǎo mǎ","to scan a QR code","",[["扫码加我吧。","Sǎo mǎ jiā wǒ ba.","Scan my code to add me."]]],["二维码","èr wéi mǎ","QR code","",[["这是我的二维码。","Zhè shì wǒ de èrwéimǎ.","Here's my QR code."]]],["密码","mì mǎ","password; PIN","Wi-Fi is usually just said in English (wāi fāi).",[["WiFi密码是多少？","WiFi mìmǎ shì duōshao?","What's the Wi-Fi password?"]]],["充电宝","chōng diàn bǎo","power bank","",[["这里能借充电宝吗？","Zhèli néng jiè chōngdiàn bǎo ma?","Can I rent a power bank here?"]]],["充电器","chōng diàn qì","charger","",[["能借一下你的充电器吗？","Néng jiè yíxià nǐ de chōngdiànqì ma?","Can I borrow your charger?"]]],["外卖","wài mài","food delivery; takeout","",[["我们点外卖吧。","Wǒmen diǎn wàimài ba.","Let's order takeout."]]],["快递","kuài dì","courier; parcel","",[["你的快递到了！","Nǐ de kuàidì dào le!","Your parcel's here!"]]],["取件码","qǔ jiàn mǎ","pick-up code (for parcels)","",[["我把取件码发给你。","Wǒ bǎ qǔ jiàn mǎ fā gěi nǐ.","I'll send you the pick-up code."]]],["放门口","fàng mén kǒu","to leave at the door","",[["放门口就行，谢谢！","Fàng ménkǒu jiù xíng, xièxie!","Just leave it at the door, thanks!"]]],["地址","dì zhǐ","address","",[["地址发我一下。","Dìzhǐ fā wǒ yíxià.","Send me the address."]]],["验证码","yàn zhèng mǎ","verification code","",[["验证码收到了吗？","Yànzhèng mǎ shōudào le ma?","Did you get the verification code?"]]],["流量","liú liàng","mobile data","",[["流量用完了。","Liúliàng yòng wánle.","I've run out of mobile data."]]],["充值","chōng zhí","to top up (credit)","",[["手机要充值了。","Shǒujī yào chōng zhí le.","My phone needs topping up."]]],["信号","xìn hào","signal (phone)","",[["这里没有信号。","Zhèli méiyǒu xìnhào.","There's no signal here."]]],["消息","xiāo xi","message; news","",[["你看到我的消息了吗？","Nǐ kàndào wǒ de xiāoxi le ma?","Did you see my message?"]]],["语音","yǔ yīn","voice message","",[["发语音吧，打字太慢。","Fā yǔyīn ba, dǎ zì tài màn.","Send a voice message, typing's too slow."]]],["视频","shì pín","video; to video-call","",[["我们晚上视频吧。","Wǒmen wǎnshang shìpín ba.","Let's video-call tonight."]]],["收到","shōu dào","to receive; got it","",[["收到，谢谢！","Shōudào, xièxie!","Got it, thanks!"]]],["房东","fáng dōng","landlord","",[["我得问一下房东。","Wǒ děi wèn yíxià fángdōng.","I need to ask the landlord."]]],["房租","fáng zū","rent","",[["这个月房租交了吗？","Zhège yuè fángzū jiāo le ma?","Have you paid this month's rent?"]]],["押金","yā jīn","deposit","",[["押金什么时候退？","Yājīn shénme shíhou tuì?","When do I get the deposit back?"]]],["水电费","shuǐ diàn fèi","water and electricity bills","",[["水电费怎么交？","Shuǐ diàn fèi zěnme jiāo?","How do I pay the utility bills?"]]],["坏了","huài le","broken; (food) gone off","",[["热水器坏了，没有热水。","Rèshuǐqì huài le, méiyǒu rèshuǐ.","The water heater's broken, there's no hot water."]]],["修","xiū","to repair; to fix","",[["师傅什么时候来修？","Shīfu shénme shíhou lái xiū?","When is the repairman coming?"]]],["空调","kōng tiáo","air conditioner","调 is tiáo here, but diào in 调查 (survey).",[["能把空调打开吗？","Néng bǎ kōngtiáo dǎkāi ma?","Can you turn on the AC?"]]],["停电","tíng diàn","power cut; to lose power","",[["楼里停电了。","Lóu lǐ tíngdiàn le.","There's a power cut in the building."]]],["物业","wù yè","property management (office)","",[["找物业来修一下吧。","Zhǎo wùyè lái xiū yíxià ba.","Get property management to fix it."]]],["楼下","lóu xià","downstairs","",[["外卖到楼下了。","Wàimài dào lóuxià le.","The delivery is downstairs."]]],["小区","xiǎo qū","residential compound","",[["这个小区很安静。","Zhège xiǎoqū hěn ānjìng.","This compound is very quiet."]]],["钥匙","yào shi","key","",[["我把钥匙忘在家里了。","Wǒ bǎ yàoshi wàng zài jiālǐ le.","I left my keys at home."]]],["洗衣机","xǐ yī jī","washing machine","",[["洗衣机怎么用？","Xǐyījī zěnme yòng?","How do I use the washing machine?"]]],["晾衣服","liàng yī fu","to hang laundry to dry","",[["阳台上可以晾衣服。","Yángtái shàng kěyǐ liàng yīfu.","You can hang laundry on the balcony."]]],["垃圾","lā jī","trash; garbage","Shanghai sorts: 干垃圾 dry, 湿垃圾 wet, 可回收物 recyclable, 有害垃圾 hazardous.",[["垃圾要分类。","Lājī yào fēnlèi.","Trash has to be sorted."]]],["银行卡","yín háng kǎ","bank card","行 is háng here (bank), not xíng.",[["我想办一张银行卡。","Wǒ xiǎng bàn yì zhāng yínhángkǎ.","I'd like to get a bank card."]]],["护照","hù zhào","passport","",[["请带上你的护照。","Qǐng dài shàng nǐ de hùzhào.","Please bring your passport."]]],["实名认证","shí míng rèn zhèng","real-name ID verification","",[["要先实名认证。","Yào xiān shí míng rènzhèng.","You need to verify your real name first."]]],["预约","yù yuē","to book; to make an appointment","",[["要提前预约吗？","Yào tíqián yùyuē ma?","Do I need to book in advance?"]]],["阿姨","ā yí","auntie; cleaner or nanny","Polite word for older women, also what you call cleaners and nannies.",[["阿姨明天来打扫。","Āyí míngtiān lái dǎsǎo.","The cleaner is coming tomorrow."]]],["理发","lǐ fà","to get a haircut","发 is fà here (hair), not fā (to send).",[["你在哪儿理发？","Nǐ zài nǎr lǐfà?","Where do you get your hair cut?"]]]]},{"id":"smalltalk","name":"Meeting people","zh":"聊天","group":"Topics","desc":"Introducing yourself, small talk and making friends.","words":[["叫什么名字","jiào shén me míng zi","what's (your) name","To strangers or elders, more polite: 您贵姓？ (What's your surname?)",[["你叫什么名字？","Nǐ jiào shénme míngzi?","What's your name?"]]],["很高兴认识你","hěn gāo xìng rèn shi nǐ","nice to meet you","",[["你好，很高兴认识你！","Nǐ hǎo, hěn gāoxìng rènshi nǐ!","Hi, nice to meet you!"]]],["你呢","nǐ ne","and you?","",[["我是英国人，你呢？","Wǒ shì Yīngguó rén, nǐ ne?","I'm British, and you?"]]],["哪国人","nǎ guó rén","which country (someone is from)","",[["你是哪国人？","Nǐ shì nǎ guó rén?","Which country are you from?"]]],["哪里人","nǎ lǐ rén","where (hometown) someone is from","Asks hometown or province; for nationality ask 你是哪国人？",[["你是哪里人？","Nǐ shì nǎli rén?","Where are you from? (hometown)"]]],["做什么工作","zuò shén me gōng zuò","what do (you) do for work","",[["你是做什么工作的？","Nǐ shì zuò shénme gōngzuò de?","What do you do for a living?"]]],["上班","shàng bān","to go to work; to work","",[["你在哪儿上班？","Nǐ zài nǎr shàngbān?","Where do you work?"]]],["学生","xué sheng","student","",[["我还是学生。","Wǒ háishi xuésheng.","I'm still a student."]]],["会说一点儿","huì shuō yì diǎn r","can speak a little","",[["我会说一点儿中文。","Wǒ huì shuō yìdiǎnr Zhōngwén.","I can speak a little Chinese."]]],["学中文","xué Zhōng wén","to study Chinese","",[["你为什么学中文？","Nǐ wèishénme xué Zhōngwén?","Why are you learning Chinese?"]]],["来中国多久了","lái Zhōng guó duō jiǔ le","how long (you've) been in China","",[["你来中国多久了？","Nǐ lái Zhōngguó duōjiǔ le?","How long have you been in China?"]]],["中文说得很好","Zhōng wén shuō de hěn hǎo","(your) Chinese is very good","得 (de) links verb and complement: 说得很好, not 说的很好.",[["你中文说得很好！","Nǐ Zhōngwén shuō de hěn hǎo!","Your Chinese is really good!"]]],["哪里哪里","nǎ lǐ nǎ lǐ","not at all (modest reply to praise)","Classic modest reply; younger people often just say 谢谢 or 还行吧.",[["哪里哪里，过奖了。","Nǎli nǎli, guòjiǎng le.","Not at all, you flatter me."]]],["还差得远","hái chà de yuǎn","still a long way to go","差 is chà here (lacking), not chā or chāi.",[["我的中文还差得远呢。","Wǒ de Zhōngwén hái chà de yuǎn ne.","My Chinese still has a long way to go."]]],["习惯","xí guàn","to be used to; habit","",[["在上海住得习惯吗？","Zài Shànghǎi zhù de xíguàn ma?","Are you used to living in Shanghai?"]]],["第一次","dì yī cì","the first time","",[["你是第一次来中国吗？","Nǐ shì dìyī cì lái Zhōngguó ma?","Is this your first time in China?"]]],["住","zhù","to live (somewhere); to stay","",[["你住在哪个区？","Nǐ zhù zài nǎge qū?","Which district do you live in?"]]],["老家","lǎo jiā","hometown","",[["你老家在哪儿？","Nǐ lǎojiā zài nǎr?","Where's your hometown?"]]],["爱好","ài hào","hobby","好 is hào here (to like), not hǎo.",[["你有什么爱好？","Nǐ yǒu shénme àihào?","What are your hobbies?"]]],["有空","yǒu kòng","to be free; to have time","空 is kòng here (free time), not kōng (empty).",[["你明天有空吗？","Nǐ míngtiān yǒu kòng ma?","Are you free tomorrow?"]]],["周末","zhōu mò","weekend","",[["周末你一般干什么？","Zhōumò nǐ yìbān gànshénme?","What do you usually do at the weekend?"]]],["改天","gǎi tiān","some other day","Often a polite gesture rather than a firm plan.",[["改天一起吃饭吧！","Gǎi tiān yìqǐ chīfàn ba!","Let's grab a meal some time!"]]],["加个微信","jiā gè Wēi xìn","to add (someone) on WeChat","",[["我们加个微信吧！","Wǒmen jiā gè Wēixìn ba!","Let's add each other on WeChat!"]]],["我扫你","wǒ sǎo nǐ","I'll scan your (WeChat) code","",[["我扫你还是你扫我？","Wǒ sǎo nǐ háishi nǐ sǎo wǒ?","Shall I scan you, or you scan me?"]]],["联系","lián xì","to contact; to keep in touch","",[["有事微信联系我。","Yǒushì Wēixìn liánxì wǒ.","If anything comes up, message me on WeChat."]]],["下次见","xià cì jiàn","see you next time","",[["好的，下次见！","Hǎode, xiàcì jiàn!","OK, see you next time!"]]],["先走了","xiān zǒu le","I'm off (leaving before you)","",[["我先走了，拜拜！","Wǒ xiān zǒu le, bài bài!","I'm heading off, bye!"]]],["忙什么","máng shén me","what (you're) busy with","",[["最近在忙什么？","Zuìjìn zài máng shénme?","What have you been up to lately?"]]],["挺好的","tǐng hǎo de","pretty good; not bad","",[["最近挺好的，你呢？","Zuìjìn tǐng hǎode, nǐ ne?","Pretty good lately, and you?"]]],["真的吗","zhēn de ma","really?","",[["真的吗？太好了！","Zhēnde ma? Tài hǎo le!","Really? That's great!"]]],["多大","duō dà","how old (adults)","多大 for adults, 几岁 for children, 多大年纪 for the elderly.",[["你今年多大？","Nǐ jīnnián duō dà?","How old are you?"]]],["专业","zhuān yè","major (field of study)","",[["你学什么专业？","Nǐ xué shénme zhuānyè?","What's your major?"]]],["打算","dǎ suàn","to plan; plan","",[["你打算待多久？","Nǐ dǎsuàn dāi duōjiǔ?","How long are you planning to stay?"]]],["有意思","yǒu yì si","interesting; fun","",[["这个工作挺有意思的。","Zhège gōngzuò tǐng yǒuyìsi de.","This job is pretty interesting."]]],["聊天","liáo tiān","to chat","",[["很高兴跟你聊天！","Hěn gāoxìng gēn nǐ liáotiān!","It was nice chatting with you!"]]],["老外","lǎo wài","foreigner (colloquial)","Casual and usually not rude; 外国人 is the neutral word.",[["这儿老外很多。","Zhèr lǎo wài hěn duō.","There are lots of foreigners here."]]],["结婚","jié hūn","to get married","Age, marriage and salary are normal small-talk questions in China.",[["你结婚了吗？","Nǐ jiéhūn le ma?","Are you married?"]]]]},{"id":"health","name":"Health and emergencies","zh":"看病","group":"Topics","desc":"Pharmacy, doctor, symptoms and emergency numbers.","words":[["救命","jiù mìng","help! (emergency)","",[["救命啊！快来人！","Jiùmìng a! Kuài lái rén!","Help! Somebody come quick!"]]],["救护车","jiù hù chē","ambulance","Ambulance: 120, said yāo èr líng.",[["快叫救护车！","Kuài jiào jiùhùchē!","Call an ambulance, quick!"]]],["报警","bào jǐng","to call the police","Police: 110, said yāo yāo líng.",[["出事了，快报警！","Chūshì le, kuài bàojǐng!","Something's happened, call the police!"]]],["着火了","zháo huǒ le","fire! (something's on fire)","着 is zháo here. Fire brigade: 119 (yāo yāo jiǔ).",[["着火了！快跑！","Zháohuǒ le! Kuài pǎo!","Fire! Run!"]]],["医院","yī yuàn","hospital","",[["最近的医院在哪儿？","Zuìjìn de yīyuàn zài nǎr?","Where's the nearest hospital?"]]],["药店","yào diàn","pharmacy","",[["附近有药店吗？","Fùjìn yǒu yàodiàn ma?","Is there a pharmacy nearby?"]]],["诊所","zhěn suǒ","clinic","",[["小区旁边有个诊所。","Xiǎoqū pángbiān yǒu gè zhěnsuǒ.","There's a clinic next to our compound."]]],["不舒服","bù shū fu","to feel unwell","",[["我有点儿不舒服。","Wǒ yǒudiǎnr bù shūfu.","I don't feel very well."]]],["疼","téng","to hurt; painful","疼 and 痛 (tòng) both mean \"hurt\"; 疼 is the everyday spoken word.",[["医生，我这儿疼。","Yīshēng, wǒ zhèr téng.","Doctor, it hurts here."]]],["发烧","fā shāo","to have a fever","",[["我发烧了，三十八度。","Wǒ fāshāo le, sān shí bā dù.","I have a fever, 38 degrees."]]],["感冒","gǎn mào","cold; to catch a cold","",[["我好像感冒了。","Wǒ hǎoxiàng gǎnmào le.","I think I've caught a cold."]]],["头疼","tóu téng","headache; to have a headache","",[["头疼得厉害。","Tóuténg de lìhai.","My head really hurts."]]],["肚子疼","dù zi téng","stomach ache","",[["肚子疼，可能吃坏了。","Dùzi téng, kěnéng chī huài le.","My stomach hurts, maybe something I ate."]]],["嗓子疼","sǎng zi téng","sore throat","",[["我嗓子疼了两天了。","Wǒ sǎngzi téng le liǎng tiān le.","My throat's been sore for two days."]]],["咳嗽","ké sou","to cough; cough","",[["咳嗽好几天了。","Késou hǎo jǐ tiān le.","I've been coughing for several days."]]],["拉肚子","lā dù zi","to have diarrhea","",[["我昨天开始拉肚子。","Wǒ zuótiān kāishǐ lā dùzi.","I've had diarrhea since yesterday."]]],["过敏","guò mǐn","to be allergic; allergy","Pattern: 对 + thing + 过敏 (allergic to something).",[["我对花生过敏。","Wǒ duì huāshēng guòmǐn.","I'm allergic to peanuts."]]],["药","yào","medicine","Medicine is \"eaten\": 吃药 = to take medicine.",[["这个药一天吃几次？","Zhège yào yì tiān chī jǐ cì?","How many times a day do I take this?"]]],["处方","chǔ fāng","prescription","处 is chǔ here, not chù (place).",[["没有处方能买吗？","Méiyǒu chǔfāng néng mǎi ma?","Can I buy it without a prescription?"]]],["看病","kàn bìng","to see a doctor","",[["你应该去看病。","Nǐ yīnggāi qù kànbìng.","You should see a doctor."]]],["挂号","guà hào","to register (at a hospital)","In China you register for a department first, then see the doctor.",[["先在手机上挂号。","Xiān zài shǒujī shàng guàhào.","Register on your phone first."]]],["急诊","jí zhěn","emergency room","",[["急诊在几楼？","Jízhěn zài jǐ lóu?","Which floor is the ER on?"]]],["医生","yī shēng","doctor","In the north doctors are also called 大夫 (dài fu); 大 is dài here.",[["医生怎么说？","Yīshēng zěnme shuō?","What did the doctor say?"]]],["受伤","shòu shāng","to get hurt; injured","",[["有人受伤了！","Yǒurén shòushāng le!","Someone's hurt!"]]],["丢了","diū le","lost (something)","",[["我的护照丢了！","Wǒ de hùzhào diū le!","I've lost my passport!"]]],["被偷了","bèi tōu le","(was) stolen","",[["手机被偷了！","Shǒujī bèi tōu le!","My phone's been stolen!"]]],["帮忙","bāng máng","to help; to do a favor","帮忙 takes no object: say 帮我 or 帮我的忙, not 帮忙我.",[["需要帮忙吗？","Xūyào bāngmáng ma?","Do you need help?"]]],["派出所","pài chū suǒ","local police station","Foreigners must register their address here; hotels do it for you, but if you stay in a flat or with friends, register soon after arriving and check the current deadline.",[["我要去派出所报案。","Wǒ yào qù pàichū suǒ bào àn.","I need to report it at the police station."]]],["大使馆","dà shǐ guǎn","embassy","",[["我得联系大使馆。","Wǒ děi liánxì dàshǐguǎn.","I need to contact my embassy."]]],["输液","shū yè","to have an IV drip","In Shanghai you'll often hear 挂水 (guà shuǐ) instead.",[["医生让我输液。","Yīshēng ràng wǒ shūyè.","The doctor wants me on an IV drip."]]],["头晕","tóu yūn","dizzy","",[["站起来就头晕。","Zhàn qǐlái jiù tóuyūn.","I get dizzy when I stand up."]]],["中暑","zhòng shǔ","heatstroke; to get heatstroke","中 is zhòng here (to be hit by), not zhōng.",[["天太热，小心中暑。","Tiān tài rè, xiǎoxīn zhòng shǔ.","It's so hot, watch out for heatstroke."]]]]}]};
